// Üretilen dosya: tool/ozgun/uret.py. Yabancı Dil · Yabancı dillerden Türkçeye geçen sözcükler, dil aileleri ve dünya dilleri (orta).
const ozLanguage4Orta = <(String, String, List<String>, String)>[
  ('"Kitap, kâtip, mektup, mektep" sözcüklerinin ortak noktası aşağıdakilerden hangisidir?', 'Arapça k-t-b kökünden türemiş olmaları', ['Farsça "-hane" ekini taşımaları', 'Fransızcadan Türkçeye geçmiş olmaları', 'Eski Türkçe "bitig" sözcüğünden gelmeleri'], 'Arapçada yazmakla ilgili k-t-b kökü farklı kalıplara dökülerek kitap (yazılan), kâtip (yazan), mektup (yazılmış), mektep (yazı yeri) gibi sözcükler verir.'),
  ('Arapçada "mef\'al" kalıbı genellikle bir işin yapıldığı yeri bildirir. Bu bilgiye göre d-r-s (ders okumak) kökünden türeyen hangi sözcük "okunulan yer" anlamı taşır?', 'medrese', ['müderris', 'tedris', 'dirasat'], 'Medrese "ders okunan yer" demektir; müderris ders veren kişi, tedris ders verme eylemidir.'),
  ('Arapça "fâil" kalıbı işi yapan kişiyi gösterir. Aşağıdaki sözcüklerden hangisi bu kalıba uyar?', 'hâkim', ['mahkeme', 'hüküm', 'mahkûm'], 'Hâkim, h-k-m kökünden fâil kalıbıyla türemiş ve "hüküm veren" anlamındadır; mahkûm ise hüküm giyen kişidir.'),
  ('Arapçada "tef\'îl" kalıbı bir işin yaptırılmasını ya da yapılmasını bildiren mastar kalıbıdır. Aşağıdakilerden hangisi bu kalıba uyan bir mastardır?', 'tedris', ['müdür', 'mektep', 'mevzuat'], 'Tedris (ders verme), d-r-s kökünden tef\'îl kalıbıyla türemiştir; aynı kalıpta tebrik, tekrar, tahsil gibi sözcükler de vardır.'),
  ('"İlim, âlim, ulema, malum" sözcükleri hangi ortak kökten türemiştir?', 'ayn-l-m (bilmek)', ['k-t-b (yazmak)', 'h-k-m (hüküm vermek)', 's-l-m (esenlik)'], 'Hepsi bilmek anlamındaki ayn-l-m kökündendir: ilim (bilgi), âlim (bilgin), ulema (bilginler), malum (bilinen).'),
  ('Selam, İslam, Müslüman ve teslim sözcüklerinin ortak Arapça kökü olan s-l-m\'nin temel anlamı aşağıdakilerden hangisine en yakındır?', 'esenlik ve barış', ['yazmak ve okumak', 'yolculuk etmek ve göç', 'güç ve kuvvet'], 'S-l-m kökü esenlik, barış ve teslim olma anlamlarını taşır; selam da "esenlik" dileğidir.'),
  ('Arapça "maf\'ûl" kalıbında "meşgul" sözcüğü "uğraştırılan, meşgul edilen" demektir. Aynı kökten gelen ve "uğraş, iş" anlamı taşıyan sözcük aşağıdakilerden hangisidir?', 'meşgale', ['şikâyetname', 'meşru', 'şükran'], 'Meşgul ve meşgale ş-g-l (uğraşmak) kökündendir; meşru ş-r-a, şükran ş-k-r kökündendir.'),
  ('Bir öğrenci "cami" ve "cuma" sözcüklerinin aynı kökten geldiğini söylüyor. Bu iddiayı en iyi destekleyen açıklama hangisidir?', 'İkisi de Arapça c-m-a "toplamak, bir araya gelmek" kökündendir.', ['İkisi de Farsçada "kutsal" anlamına gelen bir kökten türemiştir.', 'İkisi de Türkçe "cem olmak" deyiminden türetilmiştir.', 'İkisi de Yunanca bir kilise teriminden alınmıştır.'], 'Cami "toplayan", cuma "toplanma günü" demektir; cemiyet, cemaat ve cümle de aynı köktendir.'),
  ('"Evlat, ahlak, esnaf, akraba" sözcükleri için aşağıdakilerden hangisi doğrudur?', 'Arapçada çoğul oldukları hâlde Türkçede tekil anlamda da kullanılırlar.', ['Farsçadan alınmış birer ikilik (dual) biçimidir.', 'Türkçe kökler üzerine Arapça ek getirilerek türetilmiştir.', 'Yalnızca Osmanlı döneminde kullanılmış, bugün ise neredeyse tamamen unutulmuştur.'], 'Evlat (veled), ahlak (hulk), esnaf (sınıf) ve akraba (karîb) Arapça çoğullardır ama Türkçede tekil gibi davranır: "bir evlat", "akrabalar".'),
  ('Arapçada "-eyn" eki ikilik (iki tane) bildirir. Buna göre "valideyn" sözcüğünün anlamı aşağıdakilerden hangisidir?', 'anne ile baba', ['iki kız kardeş', 'büyükanne ile büyükbaba', 'üvey anne'], 'Valideyn "iki ebeveyn", yani anne ve baba demektir; tarafeyn (iki taraf) ve kutbeyn (iki kutup) da aynı ekle yapılmıştır.'),
  ('Arapçada "-ât" eki birçok sözcüğe çokluk anlamı katar. Aşağıdakilerden hangisi bu ekle kurulmuş bir çoğuldur?', 'tafsilat', ['ahbap', 'havadis', 'kavaninname'], 'Tafsilat "ayrıntılar" demektir ve "-ât" ekiyle yapılmıştır; diğerleri iç çoğul (kırık çoğul) kalıplarıdır.'),
  ('"Evrak" sözcüğü aslında çoğuldur. Tekil hâli olan "varaka" sözcüğünün temel anlamı nedir?', 'yaprak', ['mühür', 'mektup', 'defterler'], 'Arapça varaka "yaprak, kâğıt yaprağı" demektir; evrak bunun çoğulu olarak "kâğıtlar, belgeler" anlamına gelir.'),
  ('Bir dil bilgisi kitabında "Evraklar masanın üstünde." cümlesi için bir yorum yapılacaktır. Hangi yorum dil tarihi açısından en doğrudur?', 'Arapça çoğul bir sözcüğe Türkçe çoğul eki de eklenmiştir.', ['Türkçe bir sözcük iki kez çoğul yapıldığı için yanlıştır.', 'Farsça bir sözcük tekil hâle getirilmiştir.', 'Sözcük Fransızca kökenli olduğu için Türkçede çoğul eki almaz.'], 'Evrak zaten Arapça çoğuldur; Türkçe konuşurlar bunu tekil gibi algıladığından "evraklar" biçimi ortaya çıkmıştır.'),
  ('"Memurin" ve "müslimin" sözcüklerinde görülen "-în" eki hangi işlevi görür?', 'eril varlıklar için çoğul yapma', ['küçültme ve sevgi bildirme', 'yer adı türetme', 'dişil varlıklar için tekil yapma'], 'Arapçada "-în" (ve "-ûn") eki eril sağlam çoğul ekidir: memurîn "memurlar", müslimîn "Müslümanlar".'),
  ('Farsçada "si" üç, "tar" tel demektir. Bu bilgiye göre Hint müziğinde kullanılan çalgılardan hangisinin adı Farsça "üç tel" anlamına gelir?', 'sitar', ['tabla', 'vina', 'sarangi'], 'Sitar, Farsça si-târ "üç tel" birleşiminden gelir; aynı mantıkla dutar "iki tel" demektir.'),
  ('Aşağıdaki sözcük gruplarından hangisinde sözcüklerin tamamı Farsça kökenlidir?', 'dost, şehir, ateş', ['dost, kitap, ateş', 'şehir, millet, ayna', 'ateş, kalem, rüzgâr'], 'Dost, şehir ve ateş Farsçadır; kitap, millet ve kalem Arapçadır.'),
  ('Farsça "-zede" eki "vurulmuş, uğramış" anlamı katar. Bu ek Türkçe bir sözcüğe getirilerek hangi sözcük türetilmiştir?', 'depremzede', ['kazazede', 'felaketzede', 'afetzede'], 'Deprem Türkçedir; kaza, felaket ve afet ise Arapça kökenlidir. Depremzede bu yüzden melez bir türetmedir.'),
  ('"Bîçare" ve "nâmert" sözcüklerindeki "bî-" ve "nâ-" ön ekleri hangi ortak işlevi görür?', 'olumsuzluk ya da yoksunluk bildirme', ['çokluk ve abartma bildirme', 'küçültme bildirme', 'yer, zaman ya da yön bildirme'], 'Bî- "-sız", nâ- "değil" anlamı verir: bîçare "çaresiz", nâmert "mert olmayan".'),
  ('Farsça "hem-" ön eki "aynı, ortak" anlamı katar. Aşağıdakilerden hangisi bu ekle kurulmuş ve "aynı şehirden olan" anlamına gelen sözcüktür?', 'hemşehri', ['hemfikir', 'hemcins', 'hemzeminlik'], 'Hemşehri "aynı şehirli" demektir; hemfikir aynı düşüncede olanı, hemcins aynı cinsten olanı anlatır.'),
  ('"Seyahatname, beyanname, vasiyetname" sözcüklerindeki "-name" ekinin anlamı hangisidir?', 'yazı, mektup, belge', ['yolcu, gezgin', 'söz veren ya da yemin eden kişi', 'mirasçı'], 'Farsça nâme "yazı, mektup" demektir; seyahatname "yolculuk yazısı", beyanname "bildiri belgesi"dir.'),
  ('Farsça "-dan" eki "bir şeyin konduğu kap" anlamı taşır. Bu bilgiye göre mum dikilen aydınlatma aracı olan "şamdan" sözcüğündeki "şam" ne demektir?', 'mum', ['akşam', 'ateş', 'ışık direği'], 'Farsça şem\' (Arapçadan) "mum" demektir; şamdan "mumluk" anlamına gelir. Çaydanlık sözcüğü de aynı ekin Türkçe çaya uygulanmasıdır.'),
  ('"Sanatkâr, hilekâr, sitemkâr" sözcüklerindeki Farsça "-kâr" eki ile Türkçedeki hangi ek benzer işlev görür?', '-ci (yapan kişi)', ['-lik (soyut ad)', '-sız (yoksunluk, eksiklik)', '-cik (küçültme)'], '-kâr bir işi yapanı ya da bir niteliği taşıyanı bildirir; Türkçede -ci/-cı eki buna yakın görev üstlenir.'),
  ('Osmanlı\'da "Darülfünun" adıyla anılan kurumun adı Arapça "dâr" (yurt, ev) ve "fünûn" (fenler, bilimler) sözcüklerinden oluşur. Bu kurum bugünkü hangi kavramın karşılığıdır?', 'üniversite', ['kütüphane', 'ilkokul', 'askerî hastane'], 'Darülfünun "bilimler yurdu" demektir ve İstanbul Üniversitesinin öncülüdür.'),
  ('"Darülaceze" adı Arapça bir tamlamadır. "Aceze" sözcüğünün "âcizler, güçsüzler" anlamına geldiği düşünülürse bu kurumun işlevi ne olmalıdır?', 'yoksul ve kimsesizleri barındırmak', ['askerî eğitim vermek', 'mahkeme işlerini görmek', 'bilimsel araştırma ve gözlem yapmak'], 'Darülaceze "güçsüzler yurdu" anlamındadır ve İstanbul\'da 1895\'ten beri kimsesizlere hizmet veren bir kurumdur.'),
  ('"Bab-ı Âli" ifadesindeki "-ı" hangi tür tamlama ekidir?', 'Farsça izafet (tamlama) eki', ['Türkçe belirtme durumu (-ı hâli) eki', 'Arapça çoğul eki', 'Türkçe iyelik eki'], 'Farsça tamlamalarda sözcükler "-ı/-i" izafetiyle bağlanır: Bâb-ı Âlî "yüce kapı" demektir ve Osmanlı\'da sadrazamlık makamını anlatır.'),
  ('"Şeyhülislam" sözcüğü Arapça "şeyh", "el-" tanımlığı ve "İslam" sözcüklerinden oluşur. Bu yapının Türkçe söz dizimindeki karşılığı nasıl olmalıdır?', 'İslam\'ın şeyhi', ['şeyhin İslam\'ı', 'İslam şeyhler', 'İslam şeyhleri topluluğu'], 'Arapça tamlamada tamlanan önce, tamlayan sonra gelir: şeyh-ül-İslâm = İslam\'ın şeyhi (en yüksek din görevlisi).'),
  ('"Darüşşafaka" adında "-ül" tanımlığının "-üş" biçiminde okunmasının nedeni nedir?', 'Tanımlıktaki l sesinin ardından gelen ş sesine benzeşmesi', ['Farsça bir kuralla l\'nin düşmesi', 'Türkçe büyük ünlü uyumunun bir gereği olarak okunması', 'Sözcüğün Yunancadan alınmış olması'], 'Arapçada "el-" tanımlığındaki l, ş, s, t, d gibi "güneş harfleri"nden önce o sese benzeşir: dâr-ül-şafaka > Dârüşşafaka.'),
  ('Fransızcada "abat" (indirmek, kesmek) ve "jour" (gün, ışık) birleşerek bir sözcük oluşturur. Bu sözcükten Türkçeye geçen ve lambanın ışığını yumuşatan parçayı anlatan sözcük hangisidir?', 'abajur', ['ajur', 'jaluzi', 'aplikasyon'], 'Abat-jour "ışığı kesen" demektir; Türkçede lambanın başlığı anlamında abajur olarak kullanılır.'),
  ('Fransızca "gens d\'armes" ifadesi "silahlı adamlar" anlamına gelir. Bu ifadeden Türkçeye geçen kurum adı hangisidir?', 'jandarma', ['garnizon', 'ordonat', 'alay komutanlığı'], 'Gendarme sözcüğü gens d\'armes ifadesinden türemiştir; Türkçeye jandarma olarak geçmiştir.'),
  ('Fransızca "petit" küçük, "carré" kare demektir. Kumaş desenleri arasında bu iki sözcüğün birleşmesinden oluşan ad hangisidir?', 'pötikare', ['ekose', 'puantiye', 'jakarlı'], 'Pötikare, petit carré yani "küçük kare" demektir; ekose ise İskoç kareli kumaştır.'),
  ('"Kaşkol" ve "kaşkorse" sözcüklerinde bulunan Fransızca "cache" öğesinin anlamı hangisidir?', 'gizleyen, örten', ['sıcak tutan', 'süsleyen', 'yünden dokunmuş'], 'Cache-col "boynu örten", cache-corset "korseyi örten" anlamındadır.'),
  ('Fransızca "croissant" sözcüğünün anlamı "hilal, büyüyen ay"dır. Bu bilgi kruvasan adlı hamur işinin hangi özelliğiyle ilişkilidir?', 'ay biçimindeki kıvrık şekliyle', ['içine konan çikolata ya da reçelle', 'sabah yenmesiyle', 'yağlı hamuruyla'], 'Kruvasan hilal biçiminde kıvrılan bir hamur işidir; adı da biçiminden gelir.'),
  ('"İskele, pruva, lostromo, pusula, fırtına" sözcüklerinin İtalyancadan geçmiş olması en çok hangi tarihsel durumla açıklanabilir?', 'Akdeniz\'de Venedik ve Ceneviz denizciliğinin etkisi', ['Haçlı Seferleri sırasında Bizans ile yapılan antlaşmalar', 'Rönesans resminin Osmanlı\'ya etkisi', 'İtalyan operasının İstanbul\'da sevilmesi'], 'Venedik ve Cenevizliler Doğu Akdeniz\'de yüzyıllarca denizcilik yaptığından "Levanten İtalyancası" denizcilik terimlerini Türkçeye taşımıştır.'),
  ('Venedik\'te salgın dönemlerinde gemiler limana girmeden önce kırk gün bekletilirdi. İtalyanca "quaranta" (kırk) sözcüğünden türeyen ve bugün de kullanılan sözcük hangisidir?', 'karantina', ['kordon', 'izolasyon', 'tecrit odası'], 'Quarantena "kırk günlük süre" demektir; Türkçeye karantina olarak geçmiştir.'),
  ('Gemi tayfalarının başı olan "lostromo" sözcüğü İtalyanca "nostromo" (bizim adamımız) sözcüğünden gelir. Sözcüğün başındaki n\'nin l\'ye dönüşmesi hangi ses olayıdır?', 'ünsüz değişmesi', ['ünlü daralması', 'hece düşmesi', 'ünlü türemesi ve uzaması'], 'Nostromo > lostromo değişiminde bir ünsüz başka bir ünsüzle yer değiştirmiştir; bu bir ünsüz değişmesidir.'),
  ('"Ahtapot" sözcüğü Yunanca "okto" (sekiz) ve "pod" (ayak) öğelerinden oluşan bir sözcükten gelir. Bu ad hayvanın hangi özelliğini anlatır?', 'sekiz kolu olmasını', ['mürekkep püskürtmesini', 'renk değiştirmesini', 'dipte yaşamasını ve saklanmasını'], 'Yunanca oktapodi "sekiz ayaklı" demektir; ahtapotun sekiz kolu vardır.'),
  ('Aşağıdaki balık adlarından hangisi Rumcadan alınmamış, Türkçe bir sözcükle verilmiştir?', 'kalkan', ['levrek', 'çipura', 'uskumru'], 'Levrek (lavraki), çipura (tsipoura) ve uskumru (skoumbri) Rumcadan gelir; kalkan balığı ise yassı ve yuvarlak biçimi nedeniyle Türkçe kalkan sözcüğüyle adlandırılmıştır.'),
  ('İngilizce "shampoo" sözcüğü, Hindistan\'daki İngilizler aracılığıyla Hintçeden alınmıştır. Hintçedeki ilk anlamı "ovmak, masaj yapmak" olan bu sözcük Türkçeye hangi biçimde geçmiştir?', 'şampuan', ['şampiyon', 'şarpi', 'şamandıra'], 'Hintçe chāmpo "bastırmak, ovmak" İngilizcede shampoo oldu, Türkçeye de şampuan olarak geçti.'),
  ('"Folklor" sözcüğü İngilizcede 1846\'da William Thoms tarafından iki sözcük birleştirilerek oluşturulmuştur. Bu sözcüklerin anlamları hangisidir?', 'halk ve bilgi', ['toprak ve kültür', 'şarkı ve dans', 'masal ve dil'], 'Folk "halk", lore "bilgi, gelenek" demektir; folklore "halk bilgisi" anlamına gelir.'),
  ('Almanca "Föhn" Alplerde esen sıcak ve kuru bir rüzgârın adıdır. Bu ad Türkçede hangi araç için kullanılan sözcüğe dönüşmüştür?', 'saç kurutma makinesi', ['elektrikli ısıtıcı', 'vantilatör', 'klima ve nem alıcı'], 'Sıcak hava üfleyen saç kurutma makinesine Almancada sıcak rüzgârdan esinle Föhn denmiş, Türkçeye fön olarak geçmiştir.'),
  ('Rusça "samovar" sözcüğü "samo" (kendi kendine) ve "varit" (kaynatmak) öğelerinden oluşur. Türkçeye geçen bu araç hangisidir?', 'semaver', ['cezve', 'demlik', 'güğümcük'], 'Samovar "kendi kendine kaynayan" demektir; Türkçeye semaver olarak geçmiştir.'),
  ('Rusçada "voda" su demektir ve "-ka" küçültme ekidir. Bu bilgiyle hangi içki adının anlamı açıklanabilir?', 'votka', ['kımız', 'kvas', 'şampanya'], 'Vodka "suyun küçültülmüşü, sucuk" anlamındadır; renksiz görünüşüyle suya benzetilmiştir.'),
  ('Türkçede soğuk iklimlerde yaşamış soyu tükenmiş fil türü için kullanılan "mamut" sözcüğü Avrupa dillerine hangi dil aracılığıyla yayılmıştır?', 'Rusça', ['Almanca', 'Fince', 'Norveççe'], 'Mamut kalıntıları ilk olarak Sibirya\'da bulunduğundan sözcük Rusça mamont biçimiyle Avrupa dillerine geçmiştir.'),
  ('"Domates, çikolata, avokado" sözcüklerinin kökeni hangi dil ailesine ya da dile uzanır?', 'Orta Amerika\'daki Nahuatl (Aztek) dili', ['Güney Avrupa\'da Pireneler çevresindeki Bask dili', 'Batı Afrika\'daki Yoruba dili', 'Güneydoğu Asya\'daki Malay dili'], 'Tomatl, xocolatl ve ahuacatl Aztek dili Nahuatl\'ın sözcükleridir; İspanyollar aracılığıyla dünyaya yayılmıştır.'),
  ('Farsçada "dâr" ağaç, "çîn" Çin demektir. Bu bilgiye göre Türkçedeki hangi baharat adı "Çin ağacı" anlamını taşır?', 'tarçın', ['zencefil', 'karanfil', 'kimyon'], 'Tarçın, Farsça dâr-çîn "Çin ağacı" biçiminden gelir; baharat tarçın ağacının kabuğudur.'),
  ('"Portakal" meyvesinin adı bir ülke adından gelir. Bu ülke hangisidir?', 'Portekiz', ['İspanya', 'Fas', 'Hindistan'], 'Bu tür turunçgiller Avrupa\'ya ve Akdeniz\'e Portekizli tüccarlar aracılığıyla yayıldığı için meyveye Portekiz\'in adı verilmiştir.'),
  ('İngilizcedeki "kiosk" (küçük satış kulübesi) sözcüğü Türkçedeki hangi sözcükten gelir?', 'köşk', ['kulübe', 'köşe', 'kafes'], 'Kiosk, Türkçe köşk sözcüğünün Fransızca kiosque aracılığıyla İngilizceye geçmiş biçimidir; köşkün aslı Farsçadır ama Avrupa\'ya Türkçe yoluyla ulaşmıştır.'),
  ('Fransızca "turquoise" (firuze taşı) sözcüğünün anlamı "Türk taşı"dır. Bu ad verilişinin nedeni aşağıdakilerden hangisi olabilir?', 'Taşın Avrupa\'ya Türk toprakları üzerinden gelmesi', ['Taşın yalnızca Türkiye\'de çıkarılması', 'Taşın Türk bayrağının rengini taşıması', 'Taşı ilk işleyip satanın İstanbullu bir Türk kuyumcu olması'], 'Firuze taşı İran ve Orta Asya\'dan çıkarılıp Avrupa\'ya Türk toprakları üzerinden ulaştırıldığından bu adı almıştır.'),
  ('Rusçada kalem anlamına gelen "karandaş" sözcüğünün Türkçe kökenli olduğu kabul edilir. Bu sözcük hangi iki Türkçe sözcüğün birleşimine dayanır?', 'kara ve taş', ['kara ve kum', 'kalem ve taş', 'kırmızı ve taş'], 'Karandaş, grafit için kullanılan "kara taş" sözcüğünden gelir; Türk dillerinden Rusçaya geçmiştir.'),
  ('Sırpça ve Boşnakçadaki "čarapa, jastuk, kašika" sözcükleri hangi Türkçe sözcüklere karşılık gelir?', 'çorap, yastık, kaşık', ['çarık, yatak, kazan', 'çanta, yastık, kepçe', 'çorba, yatak, kaşıkçı'], 'Balkan dillerine Osmanlı döneminde çok sayıda Türkçe sözcük geçmiştir; čarapa çorap, jastuk yastık, kašika kaşıktır.'),
  ('Macarcadaki "alma" (elma) ve "betű" (harf) sözcükleri hangi dil grubundan alınmış eski alıntılardır?', 'Türk dilleri (Ogur Türkçesi)', ['Slav dilleri', 'Germen dilleri', 'Roman dilleri (Latince kökenli)'], 'Macarlar Orta Avrupa\'ya yerleşmeden önce Türk boylarıyla komşuydu; alma ve Eski Türkçe bitig\'den gelen betű bu dönemin alıntılarıdır.'),
  ('Polonya ve Prusya ordularındaki mızraklı süvarilere verilen "uhlan" adı Türkçedeki hangi sözcüğe dayanır?', 'oğlan', ['ulak', 'uçbeyi', 'alay'], 'Uhlan, Lehçe ułan biçimiyle Türk dillerindeki oğlan sözcüğünden gelir.'),
  ('Satrançtaki "checkmate" (şah mat) ifadesi iki sözcükten oluşur. "Şah" Farsçadır; "mat" sözcüğünün Arapçadaki anlamı nedir?', 'öldü', ['kaçtı', 'sıkıştı', 'teslim oldu ve çekildi'], 'Şâh mâta "şah öldü" demektir; oyunun bitişini anlatır.'),
  ('Arapça "emîr" (komutan, buyruk sahibi) sözcüğü, "emîr el-bahr" (denizin emiri) gibi unvanlar aracılığıyla Avrupa dillerine hangi sözcükle geçmiştir?', 'admiral', ['emperor', 'armada', 'adjutant'], 'Admiral ve Türkçe amiral, Arapça emir sözcüğünden gelir; donanma komutanını anlatır.'),
  ('İngilizce "magazine" sözcüğü Arapça "mahâzin" (depolar) sözcüğünden gelir. Sözcüğün "dergi" anlamını kazanması nasıl açıklanabilir?', 'Dergi, çeşitli yazıların toplandığı bir depo gibi görülmüştür.', ['Dergiler ilk olarak depolarda basılmıştır.', 'Arap tüccarlar dergi satmıştır.', 'Sözcük Arapçada önce ciltli kitap ve dergi anlamına gelmiştir.'], 'Magazine önce "ambar, cephane deposu" anlamındaydı; 18. yüzyılda çeşitli yazıların toplandığı yayın anlamını kazandı. Türkçedeki mağaza da aynı köktendir.'),
  ('Gök biliminde kullanılan "zenith" (başucu) ve "nadir" (ayakucu) terimleri hangi dilden gelir?', 'Arapça', ['Yunanca', 'Latince', 'İbranice'], 'Zenith Arapça semt (er-re\'s), nadir ise nazîr "karşı" sözcüğündendir; Ortaçağda Arap gök biliminden Avrupa\'ya geçmiştir.'),
  ('Japonca "kara" boş, "oke" ise orkestra sözcüğünün kısaltmasıdır. Bu bilgiye göre hangi eğlence türünün adı "boş orkestra" anlamına gelir?', 'karaoke', ['karate', 'kabuki', 'ikebana'], 'Karaoke\'de şarkının sözsüz müziği çalınır ve sesi kişi kendisi verir; ad da bunu anlatır.'),
  ('Malay dilinde "orang" insan, "hutan" orman demektir. Bu bilgiye göre hangi hayvanın adı "orman insanı" anlamına gelir?', 'orangutan', ['goril', 'şempanze', 'babuin maymunu'], 'Orangutan, Malayca orang hutan "orman insanı" ifadesinden gelir; Borneo ve Sumatra\'da yaşar.'),
  ('"Zeitgeist" sözcüğü Almanca "Zeit" (zaman) ve "Geist" (ruh) sözcüklerinden oluşur. Bir yazar bu kavramı kullandığında neyi anlatmak ister?', 'Bir dönemin genel düşünce ve duygu iklimini', ['Bir kişinin doğum tarihini', 'Bilimkurguda zamanda yolculuk etme düşüncesini', 'Bir şehrin tarihî mimarisini'], 'Zeitgeist "çağın ruhu" demektir; bir dönemin egemen fikirlerini ve havasını anlatır.'),
  ('İngilizcedeki "coach" sözcüğü Macaristan\'daki Kocs adlı bir kasabanın adından gelir. Bu durum için en uygun açıklama hangisidir?', 'Kasabada yapılan arabalar Avrupa\'da ünlenmiş ve adı taşıta geçmiştir.', ['Kasabada ilk spor antrenörleri yetişmiştir.', 'Kasabanın adı Macarcada "öğretmen" demektir.', 'Kasaba yüzyıllar boyunca İngiliz soylu bir ailenin mülkü olmuştur.'], '15. yüzyılda Kocs\'ta yapılan yaylı at arabaları kocsi adıyla ünlendi; sözcük Avrupa dillerine yayılarak araba, sonra da antrenör anlamı kazandı.'),
  ('Karayiplerdeki Taino dilinden İspanyolca aracılığıyla İngilizceye geçen sözcükler aşağıdakilerden hangisinde birlikte verilmiştir?', 'hurricane, hammock, canoe', ['hurricane, tornado, typhoon', 'canoe, kayak, yacht', 'hammock, sofa, divan'], 'Huracán (kasırga), hamaca (hamak) ve canoa (kano) Taino dilindendir; kayak İnuit, sofa ve divan Doğu dillerinden gelir.'),
  ('"Boykot" sözcüğü 1880\'de İrlanda\'da kiracılarına sert davrandığı için çevresi tarafından dışlanan bir kâhyanın soyadından gelir. Bu bilgiye göre sözcüğün anlamı hangisidir?', 'Bir kişi ya da kuruluşla ilişkileri toplu olarak kesmek', ['Bir işe başlamadan önce yemin etmek', 'Kiraları toplu olarak artırmak', 'Bir yöneticiyi seçimle göreve getirmek ve onu desteklemek'], 'Charles Boycott\'a karşı halk ilişkileri keserek tepki göstermiş, soyadı bu tür toplu dışlamanın adı olmuştur.'),
  ('Fransa\'nın Portekiz elçisi Jean Nicot, 16. yüzyılda tütünü Fransa sarayına tanıtmıştır. Onun adından türeyen kimyasal madde hangisidir?', 'nikotin', ['kafein', 'morfin', 'tanen'], 'Tütün bitkisinin bilimsel adı Nicotiana ve içindeki nikotin, Jean Nicot\'nun adından gelir.'),
  ('"Şovenizm" sözcüğü Napolyon\'a aşırı bağlılığıyla bilinen, belki de efsanevi olan Nicolas Chauvin adlı bir askerin adından gelir. Sözcüğün bugünkü anlamı hangisidir?', 'Aşırı ve saldırgan milliyetçilik', ['Savaş karşıtı barışçılık', 'Askerlikten kaçma', 'Yabancı kültürlere hayranlık ve öykünme'], 'Şovenizm, kendi ulusunu körü körüne yüceltip ötekileri küçümseyen aşırı milliyetçiliği anlatır.'),
  ('Elektrik potansiyel farkının uluslararası birimi olan "volt", hangi bilim insanının adından türetilmiştir?', 'Alessandro Volta', ['André-Marie Ampère', 'Michael Faraday', 'Georg Simon Ohm'], 'İlk elektrik pilini yapan İtalyan bilim insanı Volta\'nın adı potansiyel farkı birimine verilmiştir.'),
  ('Uzun mesafe koşusunun adı olan "maraton", MÖ 490\'daki bir savaştan sonra koşarak zafer haberini Atina\'ya ulaştıran habercinin efsanesine dayanır. Bu ad neyin adıdır?', 'Savaşın yapıldığı ovanın', ['Haberciyi gönderen komutanın', 'Haber götürülen tapınağın', 'Koşucunun doğduğu adanın'], 'Maraton, Atina\'nın kuzeydoğusundaki ovanın adıdır; Atinalılar Perslerle burada savaşmıştır.'),
  ('Farsçada "çehar" dört, "penc" beş, "şenbe" gün (hafta günü) anlamındadır. Bu bilgiyle hangi iki gün adının kökeni açıklanabilir?', 'Çarşamba ve Perşembe', ['Pazar ve Salı', 'Cuma ve Cumartesi', 'Salı ve Pazartesi'], 'Çarşamba "dördüncü gün", Perşembe "beşinci gün" demektir; sayım Farsçada cumartesi sonrasından başlar.'),
  ('"Pazartesi" gün adının yapısı için hangisi doğrudur?', 'Farsça "pazar" ile Türkçe "ertesi" sözcüklerinin birleşimidir.', ['Arapça bir sözcüğün tek başına söylenişidir.', 'İki Farsça sözcüğün birleşimidir.', 'Latince bir sözcükten bozulmuştur.'], 'Pazartesi "pazar ertesi" demektir; benzer biçimde Cumartesi de "Cuma ertesi"dir.'),
  ('Fransızca "lundi" (pazartesi) ve İngilizce "Monday" sözcükleri aynı gök cismine göre adlandırılmıştır. Bu gök cismi hangisidir?', 'Ay', ['Güneş', 'Mars', 'Venüs'], 'Lundi Latince "Luna" (Ay), Monday ise "Moon" ile ilgilidir; ikisi de "Ay\'ın günü" demektir.'),
  ('Latince "septem" yedi, "octo" sekiz demektir. Buna karşın Batı dillerinde September dokuzuncu, October onuncu aydır. Bu kaymanın nedeni nedir?', 'Eski Roma takviminde yılın Mart\'ta başlaması', ['Ay takviminden güneş takvimine geçilmesi', 'Ortaçağda iki yeni ayın sona eklenmesi', 'Latince sayıların yanlış çevrilmesi'], 'Eski Roma takvimi Mart\'la başladığı için Eylül yedinci, Ekim sekizinci aydı; yılbaşı Ocak\'a alınınca adlar sayılarıyla uyumsuz kaldı.'),
  ('Latincede "argentum" gümüş demektir. Güney Amerika\'da adı bu sözcükten türemiş olan ülke hangisidir?', 'Arjantin', ['Şili', 'Uruguay', 'Kolombiya Cumhuriyeti'], 'İspanyol kâşifler bölgede gümüş bulacaklarını umdukları için Río de la Plata (Gümüş Irmağı) çevresine bu adı vermiştir; Arjantin de "gümüşten" demektir.'),
  ('Karadağ\'ın Batı dillerindeki adı "Montenegro", Venedik İtalyancasından gelir. Bu ad Türkçedeki adıyla nasıl bir ilişki içindedir?', 'İki ad da aynı anlamı taşır.', ['İki ad birbirinin karşıt anlamlısıdır.', 'Türkçe ad İtalyanca adın kısaltmasıdır.', 'Batı dillerindeki ad bir krallık unvanından gelir.'], 'Monte "dağ", negro "kara" demektir; Karadağ ile Montenegro aynı anlamdaki adlardır, yerel adı Crna Gora da öyledir.'),
  ('"Belarus" ülke adının Türkçe anlamı aşağıdakilerden hangisidir?', 'Beyaz Rusya', ['Kuzey Rusya', 'Küçük Rusya', 'Batı Rusya ve Baltık ülkeleri'], 'Bela "beyaz" demektir; Belarus "Beyaz Rus" anlamına gelir.'),
  ('Batı Afrika\'daki Sierra Leone\'nin adı Portekizce "Serra Leoa" ifadesinden gelir. Bu adın anlamı hangisidir?', 'aslan dağları', ['altın kıyısı', 'fil dişi', 'yeşil burun'], 'Portekizli denizciler kıyıdaki dağlara "Aslan Dağları" adını vermiştir; Fildişi Sahili ve Yeşil Burun (Cabo Verde) başka ülkelerin adlarıdır.'),
  ('Bir öğrenci "radyo, doktor, otobüs" sözcüklerinin Türkçe olmadığını hangi ses özelliğinden anlayabilir?', 'İlk heceden sonra o ya da ö ünlüsü bulunmasından', ['Sözcük sonunda tonlu ünsüz bulunmasından', 'Sözcük başında ğ sesi bulunmasından', 'Bütün ünlülerin ince olmasından ve vurgunun sonda bulunmasından'], 'Türkçe sözcüklerde o ve ö yalnızca ilk hecede bulunur (-yor eki dışında); radyo, doktor ve otobüs bu kuralı bozar.'),
  ('Türkçe sözcükler eski dönemde "r" sesiyle başlamazdı. Bu bilgi aşağıdaki sözcüklerden hangisinin alıntı olduğunu gösterir?', 'renk', ['yeşil', 'boya', 'kızıl'], 'Renk Farsçadır; başında r bulunması da yabancı kökenli olduğunu gösteren ipuçlarındandır.'),
  ('Türkçede yansıma sözcükler dışında "f" ünsüzü pek bulunmaz. Bu bilgiye göre aşağıdakilerden hangisinin alıntı olma olasılığı en yüksektir?', 'fener', ['fısıltı', 'fokurdamak', 'fışırtı'], 'Fısıltı, fokurdamak ve fışırtı ses taklidiyle oluşmuş Türkçe sözcüklerdir; fener ise Rumcadır.'),
  ('Aşağıdaki sözcüklerden hangisi büyük ünlü uyumuna uyduğu hâlde Türkçe kökenli değildir?', 'hediye', ['kapı', 'kitap', 'kardeş'], 'Hediye Arapçadır ama e-i-e ünlüleriyle uyuma uyar; kapı Türkçedir ve uyar, kitap alıntıdır ve uymaz, kardeş Türkçedir ama uymaz. Bu yüzden ünlü uyumu tek başına köken ölçütü değildir.'),
  ('Arapça "his" sözcüğü "etmek" yardımcı eylemiyle birleşince "hissetmek" biçimini alır. Bu birleşmede görülen ses olayı hangisidir?', 'ünsüz ikizleşmesi', ['ünlü düşmesi', 'ünsüz yumuşaması', 'ünlü daralması ve uzama'], 'Arapçada kökü çift ünsüzlü olan his(s), af(f), zan(n) gibi sözcükler ünlüyle başlayan bir ek ya da eylemle birleşince ikiz ünsüz ortaya çıkar.'),
  ('Aşağıdaki birleşik eylemlerin hangisinde ünsüz ikizleşmesi görülmez?', 'kaybetmek', ['affetmek', 'zannetmek', 'reddetmek'], 'Kaybetmek\'te kayıp sözcüğündeki ı düşmüştür (ünlü düşmesi); diğerlerinde af > affetmek gibi ikizleşme vardır.'),
  ('"Sabır, emir, şükür" sözcükleri "etmek" ile birleştiğinde nasıl yazılır?', 'sabretmek, emretmek, şükretmek', ['sabıretmek, emiretmek, şükür etmek', 'sabbetmek, emmetmek, şükketmek', 'sabır etmek, emir etmek, şükür etmek'], 'Bu sözcüklerde ikinci hecedeki dar ünlü düşer ve sözcükler bitişik yazılır: sabretmek, emretmek, şükretmek.'),
  ('"Akıl" sözcüğüne ünlüyle başlayan bir ek getirildiğinde "aklı" biçimi ortaya çıkar. Aynı ses olayı aşağıdaki alıntı sözcüklerin hangisinde görülür?', 'fikir → fikri', ['kalem → kalemi', 'hayat → hayatı', 'bahçe → bahçesi'], 'Fikir > fikri, isim > ismi, akıl > aklı örneklerinde ikinci hecedeki dar ünlü düşer.'),
  ('"Bu yıl şirket büyük bir ... elde etti." cümlesinde boşluğa hangi yazım uygundur?', 'kâr', ['kar', 'kâra', 'karlar'], 'Kâr "kazanç" demektir ve düzeltme işaretiyle yazılır; kar ise yağış türüdür.'),
  ('"Kâğıt, rüzgâr, dükkân" sözcüklerinde düzeltme işaretinin kullanılma nedeni hangisidir?', 'k ve g ünsüzlerinin ince okunduğunu göstermek', ['Sözcüğün çoğul olduğunu göstermek', 'Sözcüğün Türkçe olduğunu belirtmek', 'Vurgunun ilk hecede olduğunu göstermek'], 'Bu sözcüklerde kalın a ünlüsünden önceki k ve g ince söylenir; düzeltme işareti bu inceliği gösterir.'),
  ('"Bu ... köyümüzde uzun zamandır sürüyor." cümlesinde boşluğa "gelenek" anlamı veren sözcük hangi yazımla yazılmalıdır?', 'âdet', ['adet', 'adât', 'âdât'], 'Âdet "gelenek, alışkanlık", adet "sayı" demektir; düzeltme işareti anlam farkını gösterir.'),
  ('Bilişim alanındaki "software" ve "hardware" kavramlarının Türkçe karşılıkları sırasıyla hangisidir?', 'yazılım – donanım', ['donanım – yazılım', 'uygulama – aygıt', 'program – makine'], 'Software bilgisayarın programlarını, hardware fiziksel parçalarını anlatır; karşılıkları yazılım ve donanımdır.'),
  ('"Sual, cevap, misal, lisan" sözcüklerinin Türkçe karşılıkları hangi sırayla verilmiştir?', 'soru, yanıt, örnek, dil', ['soru, örnek, yanıt, lehçe', 'dil, soru, örnek, yanıt', 'yanıt, soru, dil, örnek'], 'Sual > soru, cevap > yanıt, misal > örnek, lisan > dil karşılıklarıdır.'),
  ('İnternet kullanımında "e-mail" yerine önerilen Türkçe karşılık hangisidir?', 'e-posta', ['e-mektup', 'e-ileti kutusu', 'elektronik telgraf'], 'E-mail için Türkçede e-posta karşılığı yerleşmiştir.'),
  ('Farsça -hane ekiyle kurulmuş aşağıdaki yer adlarından hangisinde ek, Türkçe kökenli bir sözcüğe getirilmiştir?', 'Tophane', ['kütüphane', 'hastane', 'postane'], 'Top Türkçedir; kütüp (kitaplar) Arapça, hasta Farsça, posta İtalyancadır. Tophane bu yüzden Türkçe kök + Farsça ek yapısındadır.'),
  ('"Kalfa" sözcüğü Arapça "halîfe" (yerine geçen, ardıl) sözcüğünden gelir. Türkçede bu sözcüğün geçirdiği anlam değişmesi nasıl nitelendirilebilir?', 'Yüce bir makamdan zanaatta usta yardımcısına doğru anlam kayması', ['Somut bir nesneden soyut bir kavrama geçiş', 'Olumsuz bir anlamdan olumlu bir anlama yükselme', 'Anlamın hiç değişmeden korunması'], 'Halife önce Hz. Muhammed\'in ardılı anlamındaydı; esnaf örgütünde ustanın yardımcısı anlamına kaymış ve kalfa biçimini almıştır.'),
  ('Arapça "mahalle" sözcüğü "konaklanan, inilen yer" anlamındaki bir kökten gelir. Türkçedeki bugünkü anlamı aşağıdakilerden hangisidir?', 'Bir kentin yerleşim birimlerinden her biri', ['Bir kervanın konakladığı han', 'Bir köyün en eski evi', 'Bir dağın eteğindeki düzlük'], 'Mahalle, kentin yönetim ve yerleşim bakımından ayrılmış bölümlerinden biridir.'),
  ('"Otomobil" sözcüğündeki "oto" öğesi Yunanca "autos" (kendi) sözcüğünden gelir. Bu öğenin anlamıyla en uyumlu sözcük hangisidir?', 'otobiyografi', ['otopark', 'otogar', 'otoban'], 'Otobiyografi "kişinin kendi yaşamını yazması" demektir; otopark, otogar ve otoban ise "otomobil" anlamındaki kısaltılmış oto\'yu taşır.'),
  ('Yunanca "hydro" su, "phobos" korku demektir. Buna göre "hidrofobi" hangi anlama gelir?', 'su korkusu', ['ateş korkusu', 'yükseklik korkusu', 'kalabalıktan ve kapalı yerden korkma'], 'Hidrofobi "su korkusu" demektir; yükseklik korkusu akrofobi, kapalı yer korkusu klostrofobidir.'),
  ('Yunanca "demos" halk, "kratos" güç, yönetim demektir. Aynı "kratos" öğesini taşıyan ve "soyluların yönetimi" anlamına gelen kavram hangisidir?', 'aristokrasi', ['demografi', 'monarşi', 'oligarşi'], 'Aristokrasi aristos (en iyi, soylu) + kratos\'tan oluşur; monarşi ve oligarşi -arkhia (önderlik) öğesini taşır.'),
  ('Latince "aqua" su demektir. Bu kökü taşıyan ve sucul canlıların sergilendiği yapıyı anlatan sözcük hangisidir?', 'akvaryum', ['arboretum', 'teraryum', 'planetaryum'], 'Akvaryum aqua köküyle kurulmuştur; teraryum terra (toprak), planetaryum planeta, arboretum arbor (ağaç) kökünü taşır.'),
  ('Yunanca "philos" seven, "sophia" bilgelik demektir. Bu öğelerden oluşan "felsefe" sözcüğünün anlamı hangisidir?', 'bilgelik sevgisi', ['sevgi bilimi', 'doğa bilgisi', 'düşünme sanatı ve tartışma'], 'Felsefe, philosophia "bilgelik sevgisi" sözcüğünün Arapça aracılığıyla Türkçeye geçmiş biçimidir.'),
  ('Yunanca "poly" çok, "glotta" dil demektir. Buna göre "poliglot" kime denir?', 'birçok dil bilen kişiye', ['çok konuşan kişiye', 'dil bilgisi öğretmenine', 'çeviri yapılan bürolara ve çevirmenlere'], 'Poliglot "çok dilli" demektir; birden çok dili iyi bilen kişiyi anlatır.'),
  ('Sayıların akrabalığa kanıt olarak kullanılması nedeniyle şu karşılaştırma yapılmıştır: Sanskritçe "trayas", Latince "tres", Rusça "tri", İngilizce "three". Bu sözcüklerin anlamı nedir?', 'üç', ['iki', 'dört', 'on'], 'Hint-Avrupa dillerinde "üç" sayısı tr- ile başlayan benzer biçimler gösterir; bu, ortak kökenin klasik kanıtlarındandır.'),
  ('Bir dil bilimci Türkçe "kitap" ile Svahilice "kitabu" sözcüklerinin benzerliğine bakarak iki dilin akraba olduğunu söylüyor. Bu çıkarımdaki hata nedir?', 'İki dil de sözcüğü Arapçadan almıştır; alıntı akrabalık kanıtı değildir.', ['Svahili dili hiç yazılmadığı için karşılaştırma yapılamaz.', 'Sözcüklerin anlamları farklı olduğu için karşılaştırma geçersizdir.', 'Türkçe ve Svahili aynı aileden olduğu için kanıta gerek yoktur.'], 'Kitap ve kitabu, Arapça kitâb\'dan ayrı ayrı alınmıştır; ortak alıntı, dillerin akraba olduğunu göstermez.'),
  ('Latince "centum" (yüz) sözcüğü "k" sesiyle, Avesta dilindeki "satəm" ise "s" sesiyle başlar. Dil bilimciler Hint-Avrupa dillerini bu ayrıma göre iki gruba ayırmıştır. Aşağıdakilerden hangisi "satem" grubuna girer?', 'Rusça', ['Almanca', 'Yunanca', 'İtalyanca'], 'Slav, Baltık ve Hint-İran dilleri satem grubundadır; Germen, Kelt, Roman ve Yunanca ise centum grubundadır.'),
  ('Hint-Avrupa dil ailesinde kendi başına bir kol oluşturan, yani başka hiçbir dille aynı alt grupta yer almayan diller hangi seçenekte birlikte verilmiştir?', 'Arnavutça ve Ermenice', ['İspanyolca ve Portekizce', 'Çekçe ve Slovakça', 'Hintçe ve Bengalce'], 'Arnavutça ve Ermenice Hint-Avrupa ailesinin tek üyeli kollarıdır; diğer seçeneklerdeki diller büyük kolların üyeleridir.'),
  ('"Mother, Mutter, mater, mat\'" sözcükleri hangi dillere aittir ve neyi gösterir?', 'İngilizce, Almanca, Latince, Rusça; Hint-Avrupa akrabalığını', ['İngilizce, Felemenkçe, Fransızca, Lehçe; alıntı ilişkisini', 'Almanca, İsveççe, İspanyolca, Çekçe; tesadüfi benzerliği', 'İngilizce, Almanca, Yunanca, Bulgarca; aynı alfabeyi'], '"Anne" anlamındaki bu sözcükler ortak *méh₂tēr kökünden gelir ve aile içi akrabalığın tipik örneğidir.'),
  ('Hint-Avrupa ailesinin anayurdu konusunda en yaygın görüşlerden biri olan Kurgan varsayımı bu yurdu nereye yerleştirir?', 'Karadeniz\'in kuzeyindeki bozkırlara', ['İskandinav Yarımadası\'na', 'Arap Yarımadası\'na', 'Kuzey Afrika kıyılarına'], 'Marija Gimbutas\'ın geliştirdiği Kurgan varsayımına göre ilk Hint-Avrupalılar Pontus-Hazar bozkırlarında yaşamıştır; Anadolu varsayımı ise başka bir görüştür.'),
  ('Doğu Avrupa\'da konuşulduğu hâlde Roman dilleri arasında yer alan dil hangisidir?', 'Romence', ['Macarca', 'Bulgarca', 'Arnavutça'], 'Romence, Roma\'nın Dakya eyaletindeki Latinceden gelişmiştir; çevresindeki Slav ve Macar dillerinden farklı bir koldadır.'),
  ('Latince "noctem" (gece) sözcüğünün Roman dillerindeki karşılıkları aşağıdadır. Hangisi bir Roman diline ait değildir?', 'Nacht', ['notte', 'noche', 'nuit'], 'Notte İtalyanca, noche İspanyolca, nuit Fransızcadır; Nacht ise Germen dili olan Almancadır.'),
  ('İspanya\'nın kuzeydoğusunda ve Andorra\'da konuşulan, Roman ailesinden olan dil hangisidir?', 'Katalanca', ['Baskça', 'Galiçyaca', 'Bretonca'], 'Katalanca Barselona çevresinde ve Andorra\'da konuşulur; Baskça yalıtık bir dildir, Bretonca ise Kelt dilidir. Galiçyaca da Roman dilidir ama İspanya\'nın kuzeybatısındadır.'),
  ('Baltık dilleri arasında bugün yaşayan diller hangileridir?', 'Litvanca ve Letonca', ['Estonca ve Fince', 'Litvanca ve Estonca', 'Letonca ve Lehçe'], 'Baltık kolunun yaşayan dilleri Litvanca ve Letoncadır; Estonca Ural ailesinden, Lehçe ise Slav dilidir.'),
  ('Galler\'de İngilizceyle birlikte resmî statüsü olan ve "Cymraeg" diye anılan dil hangisidir?', 'Galce', ['İrlandaca', 'Kornişçe', 'Bretonca'], 'Galce (Cymraeg) Galler\'in yerli Kelt dilidir ve İngilizceyle birlikte resmî dildir.'),
  ('Hintçe ve Urduca konuşma dilinde büyük ölçüde anlaşılabilir. Bu iki dili ayıran en belirgin özellik hangisidir?', 'Hintçe Devanagari, Urduca Arap kökenli alfabeyle yazılır.', ['Hintçe Dravid, Urduca Hint-Avrupa dilidir.', 'Urduca yalnızca Hindistan\'da, Hintçe Pakistan\'da resmîdir.', 'İkisi farklı dil ailelerine aittir.'], 'Hintçe Devanagari ile yazılır ve Sanskritçe sözcükleri tercih eder; Urduca Farsça-Arapça kökenli alfabeyle yazılır ve Farsça-Arapça sözcüklere yönelir.'),
  ('Bangladeş\'in resmî dili olan ve Hindistan\'ın Batı Bengal eyaletinde de konuşulan Hint-Aryan dili hangisidir?', 'Bengalce', ['Pencapça', 'Marathice', 'Nepalce'], 'Bengalce Bangladeş\'in ulusal dilidir; Rabindranath Tagore da eserlerini bu dille yazmıştır.'),
  ('Avrupa\'da yüzyıllardır konuşulan ve Hindistan kökenli olduğu dil bilimsel olarak gösterilmiş olan dil hangisidir?', 'Romani dili', ['Arnavutça', 'Baskça', 'Romanşça'], 'Romanların dili Romani, Hint-Aryan dillerindendir; sözcük karşılaştırmaları halkın Hindistan\'dan göç ettiğini göstermiştir. Romanşça ise İsviçre\'de konuşulan bir Roman dilidir.'),
  ('Aşağıdaki Türk dillerinden hangisi Kıpçak grubuna girmez?', 'Özbekçe', ['Kazakça', 'Tatarca', 'Başkurtça'], 'Özbekçe, Uygurca ile birlikte Karluk grubundadır; Kazakça, Tatarca ve Başkurtça Kıpçak dilleridir.'),
  ('Moldova\'nın güneyinde özerk bir bölgede yaşayan ve Ortodoks Hristiyan olan bir Türk halkının dili, Türkiye Türkçesine çok yakındır. Bu dil hangisidir?', 'Gagavuzca', ['Karaimce', 'Çuvaşça', 'Kumukça'], 'Gagavuzlar Moldova\'daki Gagavuz Yeri özerk bölgesinde yaşar; dilleri Oğuz grubundandır.'),
  ('Çin\'deki Sincan Uygur Özerk Bölgesi\'ne adını veren halkın dili olan ve Arap kökenli alfabeyle yazılan Türk dili hangisidir?', 'Uygurca', ['Tuvaca', 'Yakutça', 'Gagavuzca'], 'Çağdaş Uygurca, Çin\'de Arap alfabesinin uyarlanmış biçimiyle yazılır ve Karluk grubundandır.'),
  ('Kazakistan, Kırgızistan, Özbekistan ve Türkmenistan\'ın ulusal dilleri hangi dil ailesine girer?', 'Türk dilleri', ['İran dilleri', 'Slav dilleri', 'Moğol dilleri'], 'Bu ülkelerin adını veren halkların dilleri Kazakça, Kırgızca, Özbekçe ve Türkmencedir; hepsi Türk dilidir. Tacikistan\'ın dili Tacikçe ise İran dilidir.'),
  ('Kırım\'ın yerli halklarından birinin dili olan Kırım Tatarcası için hangisi doğrudur?', 'Kıpçak temelli olup güney ağızlarında Oğuz etkisi taşır.', ['Bir Slav dilidir ve Kiril alfabesiyle doğmuştur.', 'Fince ile aynı gruptan bir Ural dilidir.', 'Moğolcanın bir ağzıdır.'], 'Kırım Tatarcasının bozkır ağızları Kıpçak, güney kıyı ağızları ise Oğuz özellikleri gösterir.'),
  ('"Şive" kavramı geleneksel dil bilgisinde aşağıdakilerden hangisiyle tanımlanır?', 'Aynı dilin daha yakın dönemde ayrılmış ve çoğunlukla ses ile söyleyiş farkı gösteren kolu', ['Bir meslek grubunun kullandığı özel sözcükler', 'Bir dilin en eski yazılı biçimi', 'Farklı dillerin karışmasıyla oluşan yeni dil'], 'Şive, lehçeye göre ana dilden daha yakın zamanda ayrılmış koldur; meslek dili ise jargon ya da argo sayılır.'),
  ('Türkiye\'de ölçünlü (standart) dil olarak kabul edilen yazı dilinin temeli hangi ağızdır?', 'İstanbul ağzı', ['Ankara ağzı', 'İzmir ağzı', 'Konya ağzı'], 'Türkiye Türkçesinin ölçünlü dili, eğitimli kesimin konuştuğu İstanbul ağzına dayanır.'),
  ('Macarcanın en yakın akrabaları, Rusya\'da Ob Irmağı çevresinde konuşulan hangi dillerdir?', 'Hantıca ve Mansiyca', ['Fince ve Estonca', 'Tatarca ve Başkurtça', 'Sırpça ve Slovakça'], 'Macarca, Batı Sibirya\'daki Hantı ve Mansi dilleriyle birlikte Ugor kolunu oluşturur.'),
  ('Kuzey İskandinavya\'da ve Rusya\'nın Kola Yarımadası\'nda yaşayan, ren geyiği çobanlığıyla bilinen yerli halkın dili hangi aileye girer?', 'Ural', ['Germen', 'Slav', 'Eskimo-Aleut'], 'Sami dilleri Ural ailesinin bir koludur; çevresindeki İsveççe ve Norveççe ise Germen dilleridir.'),
  ('Malta\'nın ulusal dili Maltaca hakkında aşağıdakilerden hangisi doğrudur?', 'Arapçadan gelişmiş bir Sami dilidir ve Latin alfabesiyle yazılır.', ['İtalyancanın bir ağzıdır.', 'Kelt ailesinden bir dildir.', 'Yunancanın Orta Çağda Arapça ile karışmasından doğmuş bir kreol dildir.'], 'Maltaca, Sicilya Arapçasından gelişmiştir ve Latin harfleriyle yazılan tek Sami dili olarak bilinir; İtalyancadan çok sözcük almıştır.'),
  ('Kuzey Afrika\'da Fas ve Cezayir\'in dağlık bölgelerinde yaygın olan, Tifinag adlı kendi yazısı da bulunan dil grubu hangisidir?', 'Berberi (Amazig) dilleri', ['Kıpti dilleri', 'Bantu dilleri', 'Kuşit (Somali-Oromo) dilleri'], 'Berberi dilleri Afro-Asya ailesinin bir koludur; Fas\'ta Amazigce resmî dil kabul edilmiştir.'),
  ('Madagaskar adasında konuşulan Malgaşça, Afrika\'ya yakın olmasına karşın hangi dil ailesindendir?', 'Austronezya', ['Bantu', 'Afro-Asya', 'Nil-Sahra ailesi'], 'Malgaşça, Borneo\'daki dillerle akrabadır; ada Güneydoğu Asya\'dan gelen denizcilerce yerleşime açılmıştır.'),
  ('Endonezce, Filipince (Tagalog), Hawaii dili ve Maori dilinin ortak özelliği nedir?', 'Dördü de Austronezya dil ailesindendir.', ['Dördü de Çin-Tibet ailesindendir.', 'Dördü de Avrupa dillerinden doğmuş kreol dillerdir.', 'Dördü de yalıtık dillerdir.'], 'Austronezya ailesi Madagaskar\'dan Paskalya Adası\'na kadar yayılan çok geniş bir alanı kaplar.'),
  ('Tayland\'ın resmî dili Tayca hangi dil ailesindendir?', 'Tay-Kaday', ['Çin-Tibet', 'Avustroasya', 'Austronezya'], 'Tayca ve Laoca Tay-Kaday (Kra-Dai) ailesindedir; ton dilidir ama Çince ile aynı aileden değildir.'),
  ('Nijerya\'nın güneybatısında konuşulan ve aynı hecenin farklı ses perdeleriyle farklı anlamlar taşıdığı Yoruba dili hangi özelliği nedeniyle Çince ile karşılaştırılır?', 'Ton dili olması', ['Logografik yazıyla yazılması', 'Sami kökenli olması', 'Eklemeli olmaması'], 'Yoruba, Niger-Kongo ailesinden bir ton dilidir; Çince ile akraba değildir ama perde farkının anlam ayırması ortaktır.'),
  ('19. yüzyılda kendi halkının dili için bir hece yazısı geliştiren ve okuma-yazma bilmeden bu işi başaran Çeroki bilge kimdir?', 'Sequoyah', ['Pocahontas', 'Oturan Boğa', 'Tecumseh'], 'Sequoyah 1821\'de Çeroki hece yazısını tamamlamış, kısa sürede halkının büyük bölümü okuryazar olmuştur.'),
  ('Aztek İmparatorluğu\'nun dili Nahuatl bugün de yaşamaktadır. Bu dil en çok hangi ülkede konuşulur?', 'Meksika', ['Peru', 'Guatemala', 'Kolombiya'], 'Nahuatl\'ın günümüzde birkaç milyon konuşuru vardır ve çoğu orta Meksika\'da yaşar.'),
  ('Türkiye\'nin Doğu Karadeniz kıyısında konuşulan Lazca, hangi dilin en yakın akrabasıdır?', 'Megrelce', ['Ermenice', 'Abhazca', 'Kabardeyce'], 'Lazca ve Megrelce Kartvel ailesinin Zan koluna girer; Abhazca ve Adigece ise Kuzeybatı Kafkas dilleridir.'),
  ('Son anadil konuşuru Tevfik Esenç\'in 1992\'de Türkiye\'de ölmesiyle anadil olarak yok olan, çok sayıda ünsüzüyle bilinen Kuzeybatı Kafkas dili hangisidir?', 'Ubıhça', ['Kabardeyce', 'Çeçence', 'Abazaca'], 'Ubıhça yaklaşık 80 ünsüz ve yalnızca birkaç ünlü içerir; dil bilimciler son konuşurundan geniş kayıtlar almıştır.'),
  ('Çeçence ve İnguşça hangi grupta yer alır?', 'Kuzeydoğu Kafkas dilleri', ['Kuzeybatı Kafkas dilleri', 'Kartvel dilleri', 'İran dilleri'], 'Çeçence ve İnguşça Nah dilleridir ve Avarca, Lezgice gibi Dağıstan dilleriyle Kuzeydoğu Kafkas ailesini oluşturur.'),
  ('İspanya ve Fransa arasındaki Pireneler bölgesinde konuşulan Baskça için aşağıdakilerden hangisi doğrudur?', 'Hint-Avrupa dillerinden önce bölgede bulunan bir dilin devamı sayılır.', ['İspanyolcanın bir ağzıdır.', 'Kelt ailesinin en eski dilidir.', 'Endülüs döneminde konuşulan Arapçanın bölgede kalmış bir kalıntısıdır.'], 'Baskça (Euskara) yalıtık bir dildir; Hint-Avrupalıların gelişinden önce Batı Avrupa\'da konuşulan dillerin hayatta kalan son temsilcisi sayılır.'),
  ('Arapçada "kitâb" (kitap), "kütüb" (kitaplar), "kâtib" (yazan) gibi sözcükler kökün içindeki ünlülerin değişmesiyle oluşur. Bu yapı hangi dil türünün özelliğidir?', 'bükümlü (çekimli) dil', ['eklemeli dil', 'yalınlayan dil', 'birleşik ve bağlantılı dil'], 'Arapça ve diğer Sami dilleri iç bükümlüdür: anlam, kökü oluşturan ünsüzlerin çevresindeki ünlülerin değişmesiyle sağlanır.'),
  ('Gelişmiş ek sistemleriyle tek bir sözcüğün bütün bir cümleyi karşılayabildiği "birleşken (polisentetik)" dillere en çok hangi bölgede rastlanır?', 'Kuzey Amerika\'nın yerli ve kutup dillerinde', ['Batı Avrupa\'nın Roman dillerinde', 'Güneydoğu Asya\'nın ton dillerinde', 'Arap Yarımadası\'nda konuşulan Sami dillerinde'], 'İnuit dilleri ve birçok Kuzey Amerika yerli dili, eylemin içine nesne ve başka öğeleri katarak çok uzun sözcükler kurar.'),
  ('Mandarin Çincesinde "ma" hecesi farklı ses perdeleriyle söylendiğinde "anne", "kenevir", "at" ya da "azarlamak" anlamına gelebilir. Bu durum dilin hangi özelliğidir?', 'ton dili olması', ['vurgu dili olması', 'eklemeli dil olması', 'ünlü uyumlu dil olması'], 'Ton dillerinde hecenin perdesi anlam ayırt eder; Mandarin Çincesinde dört temel ton vardır.'),
  ('Aşağıdaki dillerden hangisi ton dili değildir?', 'Japonca', ['Vietnamca', 'Tayca', 'Kantonca'], 'Japoncada perde vurgusu vardır ama hecelerin tonla anlam ayırdığı bir ton dili sayılmaz; Vietnamca, Tayca ve Kantonca ton dilleridir.'),
  ('Türkçede "Ali\'nin aldığı kitap" biçiminde niteleyen öğe addan önce gelirken, İngilizcede "the book that Ali bought" biçiminde addan sonra gelir. Bu fark neyle ilişkilidir?', 'Dillerin baş-öncül ya da baş-sonral olma eğilimiyle', ['Dillerin farklı alfabelerle yazılmasıyla', 'Dillerin ton dili olup olmamasıyla', 'Dillerin dil bilgisel cinsiyet taşıyıp taşımamasıyla'], 'SOV dilleri genellikle belirleyiciyi önce, başı sonra koyar (baş-sonral); SVO dilleri çoğunlukla tersini yapar.'),
  ('Japoncada kullanılan "hiragana" ve "katakana" yazıları hangi türdendir?', 'hece yazısı', ['alfabe', 'abjad', 'resim yazısı'], 'Her kana işareti bir heceyi gösterir; Japonca ayrıca Çinceden alınan kanji işaretlerini de kullanır.'),
  ('Çin yazısında her işaret çoğunlukla bir sesi değil, bir sözcüğü ya da anlamlı bir birimi gösterir. Bu yazı türüne ne ad verilir?', 'logografik yazı', ['alfabetik yazı', 'ünsüz yazısı', 'hece yazısı ve abugida'], 'Logografik yazılarda işaretler sözcük ya da biçimbirim düzeyinde anlam taşır; bu yüzden Çince binlerce işaret gerektirir.'),
  ('Moğolistan\'ın geleneksel Moğol yazısının en ayırt edici özelliği hangisidir?', 'Yukarıdan aşağıya, dikey sütunlar hâlinde yazılması', ['Sağdan sola yatay satırlarla yazılması', 'Yalnızca resim işaretlerinden oluşması', 'Harflerin hiç birleşmeden ayrı ayrı ve sağdan sola yazılması'], 'Uygur yazısından türeyen geleneksel Moğol yazısı dikey sütunlarla, soldan sağa ilerleyerek yazılır.'),
  ('Yunanlar Fenike yazısını alırken ona hangi önemli yeniliği getirmiştir?', 'Ünlüleri gösteren ayrı harfler eklemişlerdir.', ['Yazı yönünü yukarıdan aşağıya çevirmişlerdir.', 'Harfleri resim işaretlerine dönüştürmüşlerdir.', 'Harf sayısını yarıya indirmişlerdir.'], 'Yunanlar kendi dillerinde kullanmadıkları bazı Fenike ünsüz işaretlerini ünlü harflere dönüştürerek ilk tam alfabeyi oluşturmuştur.'),
  ('İskandinav ve öteki Germen halklarının Latin alfabesini benimsemeden önce taşlara kazıdıkları köşeli yazıya ne ad verilir?', 'rün yazısı', ['ogam yazısı', 'çivi yazısı', 'Glagolitik yazı'], 'Rün yazısı (futhark) Germen halklarının eski yazısıdır; ogam İrlanda Keltlerine, Glagolitik ise erken Slav metinlerine aittir.'),
  ('Gürcüce bugün kendine özgü bir alfabeyle yazılır. Bu alfabenin günümüzde kullanılan biçiminin adı hangisidir?', 'Mkhedruli', ['Glagolitik', 'Tifinag', 'Ogam'], 'Gürcü yazısının üç tarihî biçimi vardır; bugün kullanılan Mkhedruli\'dir ve büyük-küçük harf ayrımı yoktur.'),
  ('Bazı Latin harfli dillerde temel harflerin üstüne ya da altına konan "ş, ç, ñ, ø" gibi ek işaretlerin işlevi nedir?', 'Latin alfabesinde karşılığı olmayan sesleri göstermek', ['Sözcüğün yabancı kökenli olduğunu belirtmek', 'Harfin büyük harf olduğunu göstermek', 'Sözcüğün çoğul olduğunu ya da iyelik eki aldığını göstermek'], 'Latince için tasarlanan alfabe her dilin sesini karşılamadığından diller ek işaretler (aksanlar) geliştirmiştir.'),
  ('Rosetta Taşı\'nın Mısır hiyerogliflerinin çözülmesinde anahtar rol oynamasının nedeni nedir?', 'Aynı metnin Yunanca çevirisini de içermesi', ['Üzerinde bir hiyeroglif sözlüğü bulunması', 'Firavunların adlarının Latince yazılması', 'Taşın Mısırlı yazıcı öğrencilerin kullandığı bir okul tableti olması'], 'Taşta aynı ferman hiyeroglif, demotik ve Yunanca olarak yazılmıştı; bilinen Yunanca metin karşılaştırma imkânı verdi.'),
  ('Hititçenin bir Hint-Avrupa dili olduğunu 1915\'te gösteren Çek bilgin Bedřich Hrozný\'nin ilk okuduğu cümlelerden birinde "wadar" sözcüğü geçiyordu. Bu sözcüğün hangi dildeki benzeriyle karşılaştırılması ona yol göstermiştir?', 'Almanca "Wasser" ve İngilizce "water"', ['Arapça "mâ" ve İbranice "mayim"', 'Sümerce "a" ve Akadca "mû"', 'Türkçe "su" ve Moğolca "usu" sözcükleri'], 'Hrozný "ninda" (ekmek) ve "wadar" (su) sözcüklerini yorumlayarak Hititçenin Hint-Avrupa ailesinden olduğunu kanıtlamıştır.'),
  ('Sümerlerin geliştirdiği ve sonra Akadça, Hititçe gibi birçok dilin yazımında kullanılan çivi yazısının adı nereden gelir?', 'Kil tabletlere kamışla bastırılan çivi biçimli izlerden', ['Yazıtların demir çivilerle duvarlara asılmasından', 'İlk yazıların çivi ticaretiyle ilgili olmasından', 'Harflerin çivi çakarken çıkan sesi yazıda yansıtmaya çalışmasından'], 'Yazıcılar ucu üçgen kamış kalemlerle ıslak kile bastırdıklarında çivi ya da kama biçimli izler oluşuyordu.'),
  ('Türk alfabesinde bulunup İngiliz alfabesinde bulunmayan harfler hangi seçenekte doğru verilmiştir?', 'ç, ğ, ı, ö, ş, ü', ['ç, ğ, ı, ö, ş, ü, q', 'ç, ğ, ı, ö, ş, ü, w, x', 'ç, ğ, ö, ş, ü, j'], 'Türk alfabesinin 29 harfinden ç, ğ, ı, ö, ş ve ü İngilizcede yoktur; q, w ve x ise Türk alfabesinde bulunmaz.'),
  ('Uygur alfabesi hangi yazıdan türemiştir ve sonra hangi halkın yazısına kaynaklık etmiştir?', 'Soğd yazısından türemiş, Moğol yazısına kaynaklık etmiştir.', ['Çin yazısından türemiş, Kore yazısına kaynaklık etmiştir.', 'Arap yazısından türemiş, Fars yazısına kaynaklık etmiştir.', 'Yunan yazısından türemiş, Kiril yazısına kaynaklık etmiştir.'], 'Uygurlar Soğd yazısını uyarlamış, Cengiz Han döneminde Moğollar da Uygur yazısını almıştır.'),
  ('Mezopotamya\'da Sümerceden sonra yaygınlaşan, Babil ve Asur dönemlerinde kullanılan Sami dili hangisidir?', 'Akadca', ['Aramice', 'Elamca', 'Hurrice'], 'Akadca, Babilce ve Asurca ağızlarıyla çivi yazısıyla yazılmış ve uzun süre diplomasi dili olmuştur.'),
  ('Hristiyan Kutsal Kitabı\'nın Yeni Ahit bölümü, Yunancanın hangi tarihî çeşidiyle yazılmıştır?', 'Koine Yunancası', ['Homeros Yunancası', 'Miken Yunancası', 'Modern Yunanca'], 'Koine, Büyük İskender\'den sonra Doğu Akdeniz\'de yayılan ortak Yunancadır; Yeni Ahit bu dille yazılmıştır.'),
  ('Gotça hangi açıdan önemli bir dildir?', 'Belgeleri elimizde bulunan en eski Germen dillerindendir.', ['Bugün İspanya\'da konuşulan bir dildir.', 'Kelt dillerinin atasıdır.', 'Doğu Avrupa\'da konuşulmuş bir Slav dilinin eski biçimidir.'], 'Piskopos Wulfila\'nın 4. yüzyılda Gotçaya çevirdiği Kutsal Kitap parçaları, Germen dillerinin en eski uzun metinlerindendir.'),
  ('"Esperanto" sözcüğünün anlamı aşağıdakilerden hangisidir?', 'umut eden', ['evrensel dil', 'barış dili', 'dünya yurttaşlarının dili'], 'Esperanto, dili kuranın takma adıydı ve "umut eden" anlamına gelir.'),
  ('Esperantoda bütün adların "-o", sıfatların "-a" ile bitmesi gibi kurallar dilin hangi tasarım amacına hizmet eder?', 'Öğrenmeyi kolaylaştıran düzenlilik sağlamak', ['Dili Latinceye benzetmek', 'Sözcükleri uzatmak', 'Dili şiirsel ve kulağa hoş gelen bir yapıya kavuşturmak'], 'Esperanto istisnasız kurallarla tasarlanmıştır; örneğin bela (güzel) sıfatından beleco (güzellik) gibi türetmeler düzenli yapılır.'),
  ('Star Trek dizisi için dil bilimci Marc Okrand tarafından geliştirilen kurgusal dil hangisidir?', 'Klingonca', ['Dothraki', 'Na\'vi', 'Quenya'], 'Klingonca kendi dil bilgisi ve sözlüğüyle tasarlanmıştır; Dothraki Game of Thrones, Na\'vi Avatar, Quenya ise Tolkien\'in eserleri içindir.'),
  ('Tolkien\'in Orta Dünya için geliştirdiği Quenya ve Sindarin elf dilleri hangi gerçek dillerden esinlenmiştir?', 'Fince ve Galce', ['Japonca ve Korece', 'Arapça ve Farsça', 'Yunanca ve Latince'], 'Tolkien, Quenya\'nın ses düzeninde Fince, Sindarin\'de ise Galce etkisi bulunduğunu belirtmiştir.'),
  ('Esperantonun bazı kurallarını değiştirmek amacıyla 1907\'de oluşturulan ve adı Esperantoda "yavru, soy" anlamına gelen yapay dil hangisidir?', 'Ido', ['Volapük', 'Interlingua', 'Occidental'], 'Ido, Esperantonun reform edilmiş bir biçimi olarak ortaya çıkmıştır; adı "ürün, yavru" demektir.'),
  ('Bir pidgin dili ile bir kreol dili arasındaki temel fark nedir?', 'Kreol, bir topluluğun çocuklarınca anadil olarak edinilmiş ve gelişmiştir.', ['Pidgin yazılı, kreol yalnızca sözlüdür.', 'Kreol her zaman yapay olarak tasarlanır.', 'Pidgin her zaman kreolden daha karmaşık bir dil bilgisine sahiptir.'], 'Pidgin yeni kuşaklarca anadil olarak öğrenildiğinde dil bilgisi ve söz varlığı genişler; bu yeni dile kreol denir.'),
  ('Haiti\'de halkın büyük çoğunluğunun anadili olan Haiti Kreolü hangi Avrupa dilinin söz varlığına dayanır?', 'Fransızca', ['İspanyolca', 'Portekizce', 'Felemenkçe'], 'Haiti Kreolü Fransızca söz varlığı ile Batı Afrika dillerinin dil bilgisi etkisini birleştirir; Fransızcayla birlikte resmî dildir.'),
  ('Doğu Afrika\'da Kenya, Tanzanya ve Uganda\'da farklı anadilleri olan insanların ortak dili olarak kullanılan dil hangisidir?', 'Svahili', ['Amharca', 'Zuluca', 'Hausa dili'], 'Svahili, Doğu Afrika\'nın en yaygın ortak dilidir; Tanzanya ve Kenya\'da resmî dil statüsündedir.'),
  ('Ortaçağ Avrupası\'nda farklı ülkelerden bilginlerin birbirleriyle aynı dilde yazışabilmesinin temel nedeni hangisidir?', 'Latincenin bilim ve din dili olarak ortak kullanılması', ['Bütün Avrupa\'da aynı dilin konuşulması', 'İngilizcenin o dönemde yaygınlaşmış olması', 'Bilginlerin yalnızca resim yazısıyla ve sayılarla anlaşması'], 'Latince yüzyıllarca Avrupa\'nın bilim, felsefe ve kilise dili olarak bir lingua franca işlevi görmüştür.'),
  ('Belçika\'nın resmî dilleri hangileridir?', 'Felemenkçe, Fransızca ve Almanca', ['Fransızca ve İngilizce', 'Felemenkçe ve Lüksemburgca', 'Fransızca, Almanca, İtalyanca ve Romanşça'], 'Kuzeydeki Flaman bölgesi Felemenkçe, güneydeki Valon bölgesi Fransızca konuşur; doğuda küçük bir Almanca konuşan topluluk vardır.'),
  ('Kanada\'da hem İngilizce hem Fransızca resmî dildir. Fransızcanın en yaygın olduğu eyalet hangisidir?', 'Québec', ['Ontario', 'Britanya Kolumbiyası', 'Alberta'], 'Québec, Fransız sömürgesi geçmişi nedeniyle Fransızca konuşan nüfusun çoğunluğunu barındırır.'),
  ('Finlandiya\'da Fince ile birlikte resmî dil olan dil hangisidir?', 'İsveççe', ['Rusça', 'Norveççe', 'Estonca'], 'Finlandiya yüzyıllarca İsveç yönetiminde kaldığından İsveççe de resmî dil olmuştur.'),
  ('İrlanda\'nın anayasaya göre birinci resmî dili hangisidir?', 'İrlandaca', ['İngilizce', 'İskoç Galcesi', 'Galce'], 'İrlanda anayasası İrlandacayı ulusal ve birinci resmî dil, İngilizceyi ikinci resmî dil olarak tanımlar; gündelik yaşamda ise İngilizce daha yaygındır.'),
  ('İspanyolcanın resmî dil olduğu tek Afrika ülkesi hangisidir?', 'Ekvator Ginesi', ['Fas', 'Angola', 'Cabo Verde Adaları'], 'Ekvator Ginesi eski bir İspanyol sömürgesidir; Angola ve Cabo Verde Portekizce konuşur.'),
  ('Uluslararası sivil havacılıkta pilotlar ile hava trafik kontrolörleri arasındaki iletişimin standart dili hangisidir?', 'İngilizce', ['Fransızca', 'Esperanto', 'İspanyolca'], 'Uluslararası Sivil Havacılık Örgütü (ICAO) uluslararası uçuşlarda İngilizce yeterliliğini zorunlu kılar.'),
  ('İngiltere\'nin güneybatısında konuşulan, son anadil konuşurlarının 18. yüzyılın sonlarında öldüğü kabul edilen ve 20. yüzyılda canlandırılmaya çalışılan Kelt dili hangisidir?', 'Kornişçe', ['Galce', 'İrlandaca', 'Bretonca'], 'Kornişçe, Cornwall bölgesinin dilidir; bugün az sayıda kişi onu canlandırılmış biçimiyle öğrenip kullanmaktadır.'),
  ('Man Adası\'nda konuşulan Mankça (Manx), son anadil konuşuru Ned Maddrell\'in 1974\'te ölmesinden sonra hangi süreçten geçmiştir?', 'Okullar ve gönüllülerle canlandırılarak yeniden çocuklara öğretilmeye başlanmıştır.', ['Tamamen unutulmuş ve hiçbir kaydı kalmamıştır.', 'İngilizceyle birleşip yeni bir kreol oluşturmuştur.', 'Yalnızca bir yapay dile dönüştürülmüş, artık hiçbir yerde öğretilmemektedir.'], 'Mankça kayıtlar sayesinde yeniden öğrenilmiş; adada Mankça eğitim veren bir ilkokul açılmıştır.'),
  ('Bir dilin ölmesi neden yalnızca sözcüklerin kaybı değil, daha büyük bir kayıp sayılır?', 'Dil, bir topluluğun bilgisini, sözlü edebiyatını ve dünyayı kavrayış biçimini taşır.', ['Ölen dillerin sözcükleri başka hiçbir dilde karşılanamaz.', 'Ölen dilin konuşurları başka dil öğrenemez.', 'Her dil ölümü dünya ekonomisini doğrudan ve ölçülebilir biçimde küçültür, ticareti engeller.'], 'Bitki bilgisi, yer adları, masallar ve atasözleri dille aktarılır; dil kaybolunca bu kültürel birikim de büyük ölçüde yitirilir.'),
  ('Yeni Zelanda\'da Maori dilinin canlandırılması için kurulan ve küçük çocukların Maori dilinde eğitim aldığı "Kōhanga Reo" kurumlarının adı ne anlama gelir?', 'dil yuvası', ['dil okulu', 'atalar evi', 'halk meclisi'], 'Kōhanga Reo "dil yuvası" demektir; 1980\'lerde başlayan bu model başka toplulukların canlandırma çalışmalarına da örnek olmuştur.'),
  ('Türkiye\'de konuşulan diller arasında UNESCO\'nun tehlike altındaki diller listesinde yer alanlardan biri aşağıdakilerden hangisidir?', 'Lazca', ['Türkçe', 'Arapça', 'Farsça'], 'UNESCO atlası Lazca, Hemşince, Abazaca gibi dilleri Türkiye\'de tehlikedeki diller arasında sayar.'),
  ('Türkiye\'de işitme engelli bireylerin kullandığı doğal dilin adı hangisidir?', 'Türk İşaret Dili', ['Türkçe Parmak Alfabesi', 'Evrensel İşaret Dili', 'Osmanlı İşaret Kodu'], 'Türk İşaret Dili (TİD), kendi dil bilgisi olan doğal bir dildir; parmak alfabesi ise bu dilin içinde özel adları harflemek için kullanılan bir araçtır.'),
  ('İki dili anadili düzeyinde kullanabilen kişiye ne denir?', 'iki dilli', ['çok sesli', 'çift lehçeli', 'iki uyruklu'], 'İki dillilik bireyin iki dili akıcı kullanmasıdır; dünyada iki ya da çok dilli insanlar oldukça yaygındır.'),
  ('Bir İspanyolca-İngilizce iki dilli kişinin aynı cümlede "Voy al store a comprar milk." demesi hangi dil olgusuna örnektir?', 'dil değiştirme', ['halk etimolojisi', 'ses uyumu', 'dil ölümü ve dil kaybı'], 'İki dilli konuşurların bir konuşma ya da cümle içinde diller arasında geçiş yapmasına kod değiştirme denir.'),
  ('Bir dilin sözcüklerini kökenleriyle ve tarihsel gelişimleriyle inceleyen dil bilimi dalı hangisidir?', 'etimoloji', ['fonetik', 'sentaks', 'pragmatik'], 'Etimoloji sözcüklerin kökenini inceler; fonetik sesleri, sentaks cümle yapısını, pragmatik dilin bağlam içinde kullanımını araştırır.'),
  ('Bir dilde sözcükler arasındaki anlam ilişkilerini ve anlamın nasıl oluştuğunu inceleyen dil bilimi dalı hangisidir?', 'anlam bilim (semantik)', ['ses bilim (fonoloji)', 'biçim bilim (morfoloji)', 'toplum dil bilimi'], 'Semantik anlamı, fonoloji ses düzenini, morfoloji sözcüklerin yapısını, toplum dil bilimi dil ile toplum ilişkisini inceler.'),
  ('Ölçünlü bir dil, bir ülkede eğitim, basın ve resmî yazışmalarda kullanılan ortak biçimdir. Aşağıdakilerden hangisi ölçünlü dilin oluşmasına en çok katkı yapar?', 'Okullar, sözlükler ve yazım kılavuzları', ['Yalnızca köylerde konuşulan ağızlar', 'Gizli meslek dilleri', 'Yabancı turistlerin kullandığı sözcükler'], 'Ölçünlü dil eğitim kurumları, yazım kılavuzları ve basın aracılığıyla yayılır ve korunur.'),
  ('Japonca "kara" boş, "te" el demektir. Bu bilgiye göre silahsız yapılan dövüş sanatlarından hangisinin adı "boş el" anlamına gelir?', 'karate', ['judo', 'aikido', 'kendo ve kyudo'], 'Karate silahsız, yalnızca el ve ayakla yapılan bir dövüş sanatıdır; kendo ise bambu kılıçla yapılır.'),
  ('Japonca "ori" katlamak, "kami" kâğıt demektir. Bu öğelerden oluşan sanat dalının adı hangisidir?', 'origami', ['kirigami', 'manga', 'kabuki'], 'Origami kâğıt katlama sanatıdır; kirigami katlamanın yanında kesmeyi de içerir.'),
  ('Samuray sözcüğünün kökeni olan Japonca "saburau" eyleminin anlamı aşağıdakilerden hangisidir?', 'hizmet etmek', ['savaşmak', 'kılıç taşımak', 'yönetmek'], 'Samuray, bir efendiye hizmet eden savaşçı sınıfı anlamına gelir.'),
  ('Farsçada "pây" bacak, "câme" giysi demektir. Hindistan üzerinden İngilizceye, oradan Türkçeye geçen hangi sözcük bu iki öğeden oluşur?', 'pijama', ['pantolon', 'şalvar', 'peştamal'], 'Pijama, Hindistan\'da giyilen bol bacaklı giysinin Farsça adından gelir; İngilizler aracılığıyla dünyaya yayılmıştır.'),
  ('İngilizcedeki "jungle" (balta girmemiş orman) sözcüğü Hintçedeki "jangal" sözcüğünden gelir. Hintçede bu sözcüğün ilk anlamı "kurak, ıssız yer" idi. Bu durum hangi anlam olayına örnektir?', 'anlam kayması', ['ses türemesi', 'eş anlamlılık', 'kısaltma ve hece düşmesi'], 'Sözcük "ıssız yer"den "sık, bakımsız orman" anlamına kaymıştır; anlam kayması alıntılarda sık görülür.'),
  ('İspanyolca "siesta" sözcüğü Latince "sexta hora" (altıncı saat) ifadesinden gelir. Romalıların gün doğumundan saydığı altıncı saat hangi zamana denk gelir?', 'öğle saatleri', ['gece yarısı', 'sabah erken', 'akşam üstü ve gün batımı'], 'Gün doğumundan sonraki altıncı saat yaklaşık öğle vaktidir; siesta da öğle sonrası dinlenmesidir.'),
  ('İspanyolca "vainilla" sözcüğü "küçük kın, küçük kılıf" anlamına gelir. Bu adın vanilya bitkisine verilmesinin nedeni nedir?', 'Meyvesinin ince uzun bir kın biçiminde olması', ['Bitkinin kılıç yapımında kullanılması', 'Çiçeğinin kılıç kınını andırması', 'Bitkinin ilk kez bir kılıç ustasınca bulunması'], 'Vanilya orkidesinin meyvesi ince, uzun bir kapsüldür; İspanyollar ona bu biçimden ötürü "küçük kın" demiştir.'),
  ('Portekizce "marmelo" ayva demektir. Bu sözcükten türeyen ve bugün genellikle turunçgillerden yapılan reçel türünü anlatan sözcük hangisidir?', 'marmelat', ['komposto', 'jöle', 'pekmez ve pestil'], 'Marmelat ilk olarak ayvadan yapılan koyu bir tatlıydı; sonra özellikle portakal reçeli anlamında yaygınlaştı.'),
  ('Portekizce "feitiço" (büyü, yapma şey) sözcüğünden gelen ve bir nesneye doğaüstü güç yüklenmesini, mecazen de aşırı bağlılığı anlatan sözcük hangisidir?', 'fetiş', ['tabu', 'totem', 'tılsım'], 'Portekizli denizciler Batı Afrika\'daki kutsal nesnelere feitiço demiştir; sözcük fetiş olarak Avrupa dillerine yayılmıştır. Totem ve tabu ise başka dillerden gelir.'),
  ('Bir sanığın suç anında başka bir yerde bulunduğunu kanıtlaması "alibi" diye adlandırılır. Bu Latince sözcüğün anlamı hangisidir?', 'başka yerde', ['masum olarak', 'tanık önünde', 'yemin ederek'], 'Alibi Latincede "başka bir yerde" demektir; savunmanın özü de sanığın olay yerinde olmadığını göstermektir.'),
  ('İş başvurularında istenen "CV" kısaltması Latince "curriculum vitae" ifadesinden gelir. Bu ifadenin anlamı ve Türkçe karşılığı hangisidir?', 'yaşamın akışı – özgeçmiş', ['iş sözleşmesi – sözleşme', 'öğrenim belgesi – diploma', 'hayat sigortası – poliçe'], 'Curriculum vitae "yaşamın seyri" demektir; Türkçede özgeçmiş karşılığı kullanılır.'),
  ('Diplomaside "var olan durum, mevcut düzen" anlamında kullanılan Latince deyim hangisidir?', 'statüko', ['persona non grata', 'de facto', 'modus vivendi'], 'Status quo "içinde bulunulan durum" demektir; persona non grata istenmeyen kişi, de facto fiilen anlamına gelir.'),
  ('Latince "ultimus" (en son) sözcüğünden türeyen ve bir devletin ötekine son uyarısını anlatan diplomatik terim hangisidir?', 'ültimatom', ['memorandum', 'nota', 'protokol'], 'Ültimatom, karşı tarafa son şartların bildirildiği ve reddedilirse yaptırım uygulanacağını belirten uyarıdır.'),
  ('Fransızca "rendez-vous" ifadesinin sözcük anlamı "kendinizi teslim edin, gelin"dir. Türkçede "randevu" sözcüğü hangi anlamda kullanılır?', 'Önceden kararlaştırılmış buluşma', ['Resmî bir davetiye', 'Kısa bir mektup', 'Bir mağazadaki indirim'], 'Randevu belirlenen saat ve yerde buluşma ya da görüşme anlamındadır.'),
  ('Türkçede "yat" diye kullanılan lüks gezinti teknesinin adı, Felemenkçede "avlanma" anlamındaki bir sözcükten gelir. Bu adın verilmesinin olası nedeni hangisidir?', 'Hızlı ve hafif teknelerin önce korsan avlamak için kullanılması', ['Teknelerin balık avında kullanılan ağlarla donatılması', 'Avcılık kulüplerinin tekne yarışı düzenlemesi', 'Teknenin ilk sahibinin ünlü bir avcı olması'], 'Felemenkçe jacht, jachtschip (av gemisi) sözünden kısalmıştır; bu hızlı gemiler korsan ve kaçakçı kovalamak için yapılmıştı.'),
  ('Güney Afrika\'da 1948-1994 arasında uygulanan ırk ayrımcılığı politikasının adı olan "apartheid" hangi dilden gelir ve ne anlama gelir?', 'Afrikaans; ayrılık, ayrı olma durumu', ['Zuluca; zorla göç', 'İngilizce; toplu yerleşim', 'Fransızca; eşitsizlik'], 'Afrikaans, Felemenkçeden gelişmiş bir Germen dilidir; apart (ayrı) ve -heid (-lık) öğelerinden oluşan apartheid "ayrılık" demektir.'),
  ('Hint Okyanusu\'nda yılın belirli dönemlerinde yön değiştiren rüzgârların adı olan "muson" (monsoon), Arapçadaki hangi sözcükten gelir?', 'mevsim', ['muhsin', 'mizan', 'mesken'], 'Arapça mevsim "belirli zaman" demektir; denizciler bu rüzgârların belirli mevsimlerde esmesi nedeniyle bu adı kullanmıştır.'),
  ('İngilizcedeki "mattress" (şilte) sözcüğü Arapçadaki "matrah" sözcüğünden gelir. Bu Arapça sözcüğün anlamı hangisidir?', 'yere serilen şey, minder', ['yün yığını', 'uyku zamanı', 'yatak odası'], 'Matrah "atılan, serilen yer" demektir; Haçlılar döneminde Avrupa\'ya yere serilen yatak anlamında geçmiştir.'),
  ('Türkçedeki "kervan" sözcüğü Farsça kökenlidir ve İngilizceye de "caravan" biçiminde geçmiştir. İngilizcede bugün bu sözcük ek olarak hangi anlamı kazanmıştır?', 'Otomobille çekilen tekerlekli ev', ['Çölde kurulan çadır kenti', 'Deve ırklarının genel adı', 'Uzun bir yük gemisi'], 'Caravan İngilizcede hem yolcu kafilesini hem de araçla çekilen konut römorkunu anlatır; anlam genişlemesine örnektir.'),
  ('Arapça "el-iksîr" ifadesi simyacıların değersiz madenleri altına dönüştürdüğüne inandığı maddeyi anlatırdı. Bu ifadeden Avrupa dillerine geçen sözcük hangisidir?', 'elixir (iksir)', ['alcohol (alkol)', 'alkali (alkali)', 'amalgam (amalgam)'], 'El-iksîr Latince elixir biçimiyle Avrupa\'ya geçmiş, Türkçede de iksir olarak yaşamaktadır.'),
  ('Anadolu adı Yunanca "anatolē" sözcüğünden gelir. Bu sözcüğün anlamı ve bu adın kökeni hakkında hangisi doğrudur?', '"Doğu, güneşin doğduğu yer" demektir; Yunanların doğusundaki toprakları anlatır.', ['"Analar ülkesi" demektir; Türkçe kökenlidir.', '"Dağlık ada" demektir; Latince bir addır.', '"Bereketli ova" demektir; Hititçeden alınmıştır.'], 'Anatolē güneşin doğuşu ve doğu yönü demektir; "Ana dolu" açıklaması bir halk etimolojisidir.'),
  ('Yunanca "kallos" güzel, "graphein" yazmak demektir. Bu öğelerden oluşan ve güzel yazı sanatını anlatan sözcük hangisidir?', 'kaligrafi', ['tipografi', 'stenografi', 'kartografi'], 'Kaligrafi güzel yazı sanatıdır; tipografi baskı harfleri, stenografi hızlı yazı, kartografi harita yapımıdır.'),
  ('Yunanca "atomos" sözcüğü "a-" (değil) ve "tomos" (kesilen) öğelerinden oluşur. Bu ad, Eski Yunan filozoflarının atomu nasıl düşündüğünü gösterir?', 'Daha küçük parçalara bölünemeyen en küçük yapı taşı olarak', ['Sürekli kesilerek çoğalan bir madde olarak', 'Yalnızca canlılarda bulunan bir parçacık olarak', 'Ateşten oluşan görünmez bir öz olarak'], 'Demokritos atomu bölünemez parçacık olarak düşünmüştür; çağdaş fizik atomun da bölünebildiğini göstermiştir.'),
  ('1492\'de İspanya\'dan sürülüp Osmanlı topraklarına yerleşen Sefarad Yahudilerinin kuşaklar boyu konuştuğu dil hangisidir?', 'Ladino', ['Yidiş', 'Aramice', 'Kıpti dili'], 'Ladino, Eski İspanyolcaya dayanır; İstanbul, Selanik ve İzmir\'de yüzyıllarca konuşulmuş ve Türkçeden de sözcük almıştır.'),
  ('Kafkasya\'da Kuzey Osetya ve Güney Osetya\'da konuşulan Osetçe hangi dil grubundadır?', 'İran dilleri', ['Kartvel dilleri', 'Türk dilleri', 'Kuzeydoğu Kafkas dilleri'], 'Osetçe, eski Alan ve İskit dillerinin devamı sayılan bir Doğu İran dilidir.'),
  ('Avrupa\'daki Roman dilleri arasında Sardunya adasında konuşulan Sardunyaca neden ilgi çeker?', 'Latincenin ses yapısını en iyi koruyan Roman dillerinden biri olduğu için', ['Bir Germen dili olduğu hâlde Latince sözcük kullandığı için', 'Hiçbir yazılı metni olmadığı için', 'İtalyancanın tek resmî ağzı olduğu için'], 'Sardunyaca, adanın yalıtılmış konumu nedeniyle Latincenin bazı eski seslerini, örneğin bazı sözcüklerdeki k sesini korumuştur.'),
  ('Yunan alfabesinin son harfi "omega" hangi anlamdaki deyimlerde "son" simgesi olarak kullanılır?', '"Alfa ve omega" yani başlangıç ve son', ['"Omega noktası" yani ilk adım', '"Omega yolu" yani kuzey yönü', '"Omega işareti" yani soru'], 'Alfa ilk, omega son harftir; "alfa ve omega" deyimi bir şeyin başı ve sonu, yani bütünü demektir.'),
  ('Kore alfabesi Hangıl\'da harfler yan yana dizilmek yerine hece blokları hâlinde gruplanır. Bu özellik okuyucuya hangi kolaylığı sağlar?', 'Her bloğun bir heceyi göstermesiyle sözcüklerin hızlı tanınmasını', ['Ünlülerin hiç yazılmamasını', 'Yazının sağdan sola okunmasını', 'Çince karakterlerle aynı anlamı taşımasını'], 'Hangıl\'da ünsüz ve ünlü harfler bir kare içinde birleşerek hece oluşturur; bu blok yapı Çince karakterlerin görünüşüne de uyum sağlar.'),
  ('Hint-Avrupalıların anayurdunu açıklayan "Kurgan varsayımı" adını, Rusçaya Türk dillerinden geçmiş bir sözcükten alır. Bu sözcüğün anlamı nedir?', 'mezar tümseği, höyük', ['bozkır atı', 'göçebe çadırı', 'demir kılıç'], 'Kurgan, eski bozkır halklarının ölüleri için yaptığı toprak tümseklerdir; varsayım bu mezar kültürüyle ilişkilendirilmiştir.'),
  ('Türkçede adını Hindistan\'dan alan "hindi", İngilizcede "turkey" diye anılır. Bu karşılaştırma hangi sonuca götürür?', 'Hayvan adları, ürünün yanlış ya da dolaylı bilinen geliş yolundan etkilenebilir.', ['Hindi kuşunun anayurdu Türkiye\'dir.', 'Hindi kuşunun anayurdu Hindistan\'dır.', 'İki ad aynı Sanskritçe kökten gelir.'], 'Hindi aslında Amerika kıtasının kuşudur; Avrupalılar onu tüccarların getirdiği başka bir kuşla karıştırmış ve uzak doğulu yerlere göre adlandırmıştır.'),
  ('İngilizcede lokum için kullanılan ve Türkçe adından farklı olan ad hangisidir?', 'Turkish delight', ['Turkish candy', 'Ottoman sweet', 'Istanbul jelly'], 'Lokum İngilizcede "Turkish delight" (Türk lezzeti) diye bilinir.'),
  ('Farsçadaki "kaşık" anlamındaki "qāşoq" sözcüğünün kaynağı hangi dildir?', 'Türkçe', ['Arapça', 'Hintçe', 'Moğolca'], 'Farsça Türk boylarıyla yüzyıllarca iç içe yaşadığından Türkçeden çok sayıda sözcük almıştır; kaşık bunlardan biridir.'),
  ('İngilizcede "ottoman" sözcüğü bir mobilya türünü de anlatır. Bu kullanım hangi anlam olayına örnektir?', 'Özel addan cins ad türemesi', ['Ses düşmesi', 'Eş seslilik', 'Anlam daralması'], 'Osmanlı adından gelen ottoman, minderli alçak oturak anlamında cins ada dönüşmüştür.'),
  ('Sırpça ve Boşnakçada "kapija" (kapı), "boja" (boya) ve "sokak" gibi sözcüklerin bulunması hangi tarihsel olgunun dildeki izidir?', 'Balkanlarda yüzyıllar süren Osmanlı yönetimi', ['Haçlı Seferleri', 'Roma İmparatorluğu\'nun yıkılışı', 'Avusturya-Macaristan\'ın kuruluşu'], 'Osmanlı yönetimi boyunca Balkan dillerine binlerce Türkçe (ve Türkçe aracılığıyla Arapça-Farsça) sözcük girmiştir.'),
  ('Yunanca "hippos" at, "potamos" ırmak demektir. Bu öğelerden oluşan hayvan adı hangisidir?', 'hipopotam', ['hipodrom', 'hipokrat', 'potasyum'], 'Hipopotam "ırmak atı" demektir; hipodrom ise "at koşu yeri"dir.'),
  ('Yunanca "deinos" korkunç, "sauros" kertenkele demektir. 1842\'de Richard Owen\'ın bu öğelerle oluşturduğu sözcük hangisidir?', 'dinozor', ['timsah', 'iguana', 'bukalemun'], 'Dinozor "korkunç kertenkele" anlamındadır; bukalemun da Yunanca khamaileon "yer aslanı"dan gelir.'),
  ('Yunanca "mesos" orta, "potamos" ırmak demektir. "Mezopotamya" adı bölgenin hangi coğrafi özelliğini anlatır?', 'Dicle ile Fırat arasında bulunmasını', ['Yüksek dağlarla çevrili olmasını', 'Denize kıyısının bulunmamasını', 'Çöl ortasında bir vaha olmasını'], 'Mezopotamya "ırmaklar arası ülke" demektir; Dicle ve Fırat arasındaki toprakları anlatır.'),
  ('Yunanca "mikros" küçük, "bios" yaşam demektir. Bu iki öğeden türemiş olan ve Türkçede de kullanılan sözcük hangisidir?', 'mikrop', ['mikron', 'mikser', 'mikrofon'], 'Mikrop, Fransızca microbe aracılığıyla gelen "küçük canlı" anlamında bir sözcüktür; mikrofon ise "küçük ses" demektir.'),
  ('Antik Yunan\'da "tragoidia" sözcüğünün sözcük anlamı aşağıdakilerden hangisidir?', 'teke şarkısı', ['ağlayan halk', 'tanrıların öfkesi', 'kahramanın ölümü'], 'Tragos teke, ōidē şarkı demektir; adın Dionysos törenlerinde kurban edilen ya da ödül verilen tekeyle ilgili olduğu düşünülür.'),
  ('Yunanca "akros" en yüksek, "polis" kent demektir. Atina\'daki Akropolis\'in adı onun hangi özelliğini anlatır?', 'Kentin en yüksek yerinde kurulmuş olmasını', ['Kentin en kalabalık mahallesi olmasını', 'Kentin limanına yakın olmasını', 'Kentin en eski pazarı olmasını'], 'Akropolis "yukarı kent" demektir; Parthenon da bu kayalık tepenin üzerindedir. Nekropol ise "ölüler kenti" anlamına gelir.'),
  ('Gezegenler gece göğünde yıldızlara göre yer değiştirdiği için Yunanlar onlara "planētēs" adını vermiştir. Bu sözcüğün anlamı hangisidir?', 'gezgin', ['parlak', 'uzak', 'kutsal'], 'Planētēs "dolaşan, gezgin" demektir; Türkçedeki gezegen karşılığı da aynı mantıkla türetilmiştir.'),
  ('Latince "salarium" Roma askerlerine tuz almaları için verilen parayla ilişkilendirilir. Bu sözcükten İngilizceye geçen sözcük hangi anlamdadır?', 'maaş (salary)', ['salata (salad)', 'sos (sauce)', 'selam (salute)'], 'Salarium, sal (tuz) sözcüğünden türemiştir; İngilizcedeki salary aylık ücret anlamına gelir.'),
  ('Latince "calculus" küçük çakıl taşı demektir. Bu sözcüğün matematikte "hesap" anlamını kazanmasının nedeni nedir?', 'Eskiden sayma ve hesaplamada küçük taşlar kullanılması', ['Matematikçilerin taş ocaklarında çalışması', 'Geometri şekillerinin taşa kazınması', 'Taşların ağırlığıyla alan ölçülmesi'], 'Romalılar abaküs benzeri tahtalarda çakıl taşlarıyla hesap yapardı; calculate ve kalkülüs sözcükleri buradan gelir.'),
  ('Latince "Mare Mediterraneum" adı "toprakların ortasındaki deniz" anlamına gelir. Bu ad hangi denizi anlatır?', 'Akdeniz', ['Karadeniz', 'Kızıldeniz', 'Hazar Denizi'], 'Akdeniz, Avrupa, Asya ve Afrika toprakları arasında kaldığı için Romalılarca bu adla anılmıştır.'),
  ('Yunanca "phōs" ışık, "graphē" yazı demektir. Bu öğelerden oluşan ve "ışıkla yazma" anlamına gelen sözcük hangisidir?', 'fotoğraf', ['fosfor', 'fotosentez', 'fotokopi makinesi'], 'Fotoğraf ışığın duyarlı bir yüzeye görüntü yazması demektir; fotosentez ise "ışıkla birleştirme"dir.'),
  ('"Otobüs" sözcüğü Fransızca "autobus" sözcüğünden gelir; bu sözcük de "auto" ile Latince "omnibus" sözcüğünün sonundan oluşmuştur. Latince "omnibus" ne demektir?', 'herkes için', ['hızlı giden', 'büyük araba', 'şehir içi'], 'Omnibus "herkes için" demektir; 19. yüzyılda herkese açık atlı toplu taşıma arabalarına bu ad verilmişti.'),
  ('Yunanca "helix" sarmal, "pteron" kanat demektir. Bu öğelerden oluşan hava taşıtının adı hangisidir?', 'helikopter', ['planör', 'zeplin', 'paraşüt'], 'Helikopter "sarmal kanat" anlamındadır; zeplin ise mucidi Ferdinand von Zeppelin\'in adından gelir.'),
  ('"Bisiklet" sözcüğünde bulunan ve Yunanca "kyklos" (çember, tekerlek) sözcüğünden gelen öğe, aşağıdaki sözcüklerin hangisinde de vardır?', 'siklon', ['sigara', 'silindir', 'sicim'], 'Siklon, havanın çember biçiminde döndüğü fırtınadır ve kyklos kökünü taşır; bisiklet de "iki tekerlek" demektir.'),
  ('Paris\'te 1900\'de açılan yeraltı demiryolunun adı "Chemin de fer métropolitain" idi. Bugün dünyada kullanılan "metro" sözcüğü bu addan hangi yolla türemiştir?', 'kısaltma yoluyla', ['ses türemesiyle', 'ödünç çeviriyle', 'eş anlamlı sözcükten'], 'Métropolitain "anakente ait" demektir; uzun ad kısaltılarak metro biçimini almıştır.'),
  ('Mandarin Çincesi ile ilgili hangi bilgi kesindir?', 'Dünyada anadili olarak en çok kişinin konuştuğu dildir.', ['Yalnızca Tayvan\'da konuşulur.', 'Alfabe ile yazılan bir dildir.', 'Türk dilleriyle akrabadır.'], 'Mandarin Çincesinin anadil konuşur sayısı başka hiçbir dilinkine yaklaşmaz; Çin, Tayvan ve Singapur\'da resmîdir.'),
  ('"Taksi" sözcüğü, araçlarda ücreti ölçen "taksimetre" adının kısalmasıyla oluşmuştur. Taksimetre sözcüğündeki "taksi-" öğesi hangi anlamla ilişkilidir?', 'ücret, vergi', ['hız, sürat', 'yol, mesafe', 'araba, taşıt'], 'Ortaçağ Latincesindeki taxa (ücret, vergi) sözcüğüne dayanan öğe, ücreti ölçen aletin adına girmiştir.'),
  ('"Hükümdar" sözcüğünün yapısı için hangisi doğrudur?', 'Arapça "hüküm" ile Farsça "-dar" ekinin birleşimidir.', ['İki Arapça sözcüğün birleşimidir.', 'Türkçe bir kök ile Farsça bir ekin birleşimidir.', 'Moğolca bir unvanın Türkçe söylenişidir.'], 'Hüküm Arapça, -dâr Farsçadır; hükümdar "hüküm sahibi" anlamındaki melez bir yapıdır.'),
  ('Farsçada "nev" yeni, "rûz" gün demektir. Bu bilgiye göre "nevruz" sözcüğünün anlamı nedir?', 'yeni gün', ['bahar ayı', 'güneş doğuşu', 'bereketli toprak'], 'Nevruz "yeni gün" demektir; birçok toplulukta baharın ve yeni yılın başlangıcı olarak kutlanır.'),
  ('Farsçada "âb" su demektir. Kuru meyvelerin suyla kaynatılmasıyla yapılan ve adı "hoş su" anlamına gelen içecek hangisidir?', 'hoşaf', ['şerbet', 'boza', 'salep'], 'Hoşaf, Farsça hoş ve âb sözcüklerinden oluşur; şerbet Arapça, boza ve salep ise farklı kökenlidir.'),
  ('"Kervansaray" sözcüğü Farsça iki sözcüğün birleşmesinden oluşur. Bu sözcükler hangileridir?', 'kârvân (yolcu kafilesi) ve sarây (konak)', ['kâr (kazanç) ve vân (yol)', 'kervân (deve) ve sarı (renk)', 'kâr (iş) ve sarây (saray kapısı)'], 'Kervansaray, yolcu kafilelerinin konakladığı hanlara verilen addır.'),
  ('Endonezya\'nın resmî dili Endonezce hangi dilin ölçünlü biçiminden gelişmiştir?', 'Malayca', ['Cavaca', 'Felemenkçe', 'Tagalogca'], 'Endonezce, uzun süre bölgenin ticaret dili olan Malaycaya dayanır; nüfusun en kalabalık grubunun dili olan Cavaca seçilmemiştir.'),
  ('Bir dilin hangi alfabeyle yazılacağını belirleyen etkenlerden biri de din ve kültür çevresidir. Aşağıdaki örneklerden hangisi bu etkiyi en iyi gösterir?', 'Aynı Slav dil grubundan Hırvatça Latin, Sırpça ağırlıklı Kiril harflerini kullanır.', ['İngilizce ve Almanca aynı alfabeyi kullanır.', 'Fince ve Macarca akraba oldukları için aynı alfabeyi kullanır.', 'Japonca hece yazısı kullanır.'], 'Katolik Hırvatlar Latin, Ortodoks Sırplar Kiril yazısını benimsemiştir; diller çok yakın olduğu hâlde yazı farklıdır.'),
];
